    def compute_quark_energy_density(self, flavor: str, t: float = 0, 
                                      t_n: float = 0, n: int = 1) -> Tuple[float, str]:
        """
        Compute quark energy density in UQFF.
        
        U_q = λ_q × ρ_vac,[SCm] × ρ_vac,[UA] × ω_q(t) × cos(πt_n)
              × (1 + f_TRZ) × e^(-[SSq]^n × 26 × e^(-π - t))
        
        Args:
            flavor: Quark flavor ('u', 'd', 'c', 's', 't', 'b')
            t: Time (s)
            t_n: Negative time factor
            n: Quantum state (1-26)
            
        Returns:
            Tuple of (U_q in J/m³, explanation string)
        """
        if flavor not in self.quark_masses:
            flavor = 'u'  # Default to up quark
        
        lambda_q = self.quark_lambdas.get(flavor, 1.0)
        omega_q = self.quark_omegas.get(flavor, 1e20)
        
        # Compute terms
        cos_term = np.cos(np.pi * t_n)
        TRZ_factor = 1 + self.f_TRZ
        nonlocal_term, _ = self.compute_nonlocal_jump_probability(t, n)
        nonlocal_exp = np.exp(-nonlocal_term)
        
        # Energy density
        U_q = (lambda_q * self.rho_vac_SCm * self.rho_vac_UA * omega_q 
               * cos_term * TRZ_factor * nonlocal_exp)
        
        explanation = f"""
    QUARK ENERGY DENSITY ({flavor.upper()} QUARK)
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_q = λ_q × ρ_vac,[SCm] × ρ_vac,[UA] × ω_q × cos(πt_n)
              × (1 + f_TRZ) × e^(-[SSq]^n × 26 × e^(-π-t))
    
    INPUTS:
        Quark flavor: {flavor}
        λ_{flavor} = {lambda_q}
        ω_{flavor} = {omega_q:.0e} rad/s
        ρ_vac,[SCm] = {self.rho_vac_SCm:.4e} J/m³
        ρ_vac,[UA] = {self.rho_vac_UA:.4e} J/m³
        t_n = {t_n}, t = {t}, n = {n}
    
    CALCULATION:
        cos(πt_n) = cos({np.pi * t_n:.4f}) = {cos_term:.4f}
        (1 + f_TRZ) = 1 + {self.f_TRZ} = {TRZ_factor:.2f}
        Non-local term = {nonlocal_term:.6e}
        e^(-non-local) = {nonlocal_exp:.6f}
        
        U_{flavor} = {lambda_q} × {self.rho_vac_SCm:.4e} × {self.rho_vac_UA:.4e}
             × {omega_q:.0e} × {cos_term:.4f} × {TRZ_factor:.2f} × {nonlocal_exp:.6f}
           = {U_q:.4e} J/m³
    
    PHYSICAL INTERPRETATION:
        Quarks are QUANTIZED VORTICES in the superfluid [UA], with their
        energy density modulated by:
        • cos(πt_n): Time-reversal oscillation
        • f_TRZ: Time-reversal zone enhancement
        • Non-local term: Quark confinement via [SSq]^n
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_q, explanation
    
    def compute_quark_mass_energy(self, flavor: str, n: int = 1) -> Tuple[float, str]:
        """
        Compute quark mass energy modified by quantum state.
        
        Args:
            flavor: Quark flavor ('u', 'd', 'c', 's', 't', 'b')
            n: Quantum state (1-26)
            
        Returns:
            Tuple of (E_q in J, explanation string)
        """
        mass = self.quark_masses.get(flavor, self.quark_masses['u'])
        return self.compute_mass_energy_modified(mass, n)
    
    def compute_quark_electric_field(self, flavor: str, r: float) -> Tuple[float, str]:
        """
        Compute quark electric field contribution in Aether.
        
        E_field,q = (q_q) / (4πε₀r) × ρ_vac,[UA]
        
        Args:
            flavor: Quark flavor
            r: Distance from quark (m)
            
        Returns:
            Tuple of (E_field in V/m × J/m³, explanation string)
        """
        q_frac = self.quark_charges.get(flavor, 2/3)
        q_actual = q_frac * self.q  # Actual charge in C
        
        E_field = (q_actual / (4 * np.pi * self.epsilon_0 * r)) * self.rho_vac_UA
        
        explanation = f"""
    QUARK ELECTRIC FIELD IN AETHER ({flavor.upper()} QUARK)
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        E_field,q = (q_q) / (4πε₀r) × ρ_vac,[UA]
    
    INPUTS:
        q_{flavor} = {q_frac:+.3f}e = {q_actual:+.4e} C
        r = {r:.4e} m
        ε₀ = {self.epsilon_0:.4e} F/m
        ρ_vac,[UA] = {self.rho_vac_UA:.4e} J/m³
    
    CALCULATION:
        Coulomb field = q / (4πε₀r) = {q_actual / (4 * np.pi * self.epsilon_0 * r):.4e} V/m
        
        E_field,q = {E_field:.4e} V/m × J/m³
    
    PHYSICAL INTERPRETATION:
        This represents the quark's electric field contribution scaled by
        the Universal Aether [UA] vacuum energy density, showing how
        quarks interact electromagnetically within the [UA] medium.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return E_field, explanation
    
    def compute_quark_pondermotive_force(self, flavor: str, 
                                          E_SCm_gradient: float) -> Tuple[float, str]:
        """
        Compute pondermotive force on quark in TRZ.
        
        F_p,q = -(q_q²) / (4m_q ω_q²) × ∇(E²_[SCm])
        
        Args:
            flavor: Quark flavor
            E_SCm_gradient: Gradient of E²_[SCm] (V²/m³)
            
        Returns:
            Tuple of (F_p in N, explanation string)
        """
        m_q = self.quark_masses.get(flavor, self.quark_masses['u'])
        q_frac = self.quark_charges.get(flavor, 2/3)
        q_actual = q_frac * self.q
        omega_q = self.quark_omegas.get(flavor, 1e20)
        
        F_p = -(q_actual**2) / (4 * m_q * omega_q**2) * E_SCm_gradient
        
        explanation = f"""
    QUARK PONDERMOTIVE FORCE IN TRZ ({flavor.upper()} QUARK)
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        F_p,q = -(q_q²) / (4m_q ω_q²) × ∇(E²_[SCm])
    
    INPUTS:
        q_{flavor} = {q_frac:+.3f}e = {q_actual:+.4e} C
        m_{flavor} = {m_q:.4e} kg
        ω_{flavor} = {omega_q:.0e} rad/s
        ∇(E²_[SCm]) = {E_SCm_gradient:.4e} V²/m³
    
    CALCULATION:
        -(q_q²) / (4m_q ω_q²) = -{q_actual**2:.4e} / (4 × {m_q:.4e} × ({omega_q:.0e})²)
                              = {-(q_actual**2) / (4 * m_q * omega_q**2):.4e}
        
        F_p = {F_p:.4e} N
    
    PHYSICAL INTERPRETATION:
        The PONDERMOTIVE FORCE from oscillating [SCm] fields in TRZs
        contributes to negentropic effects, enabling:
        • Energy extraction with COP > 1
        • Particle confinement and trapping
        • Non-local jump facilitation
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return F_p, explanation
    
