    def validate_TRZ_physics(self) -> dict:
        """
        Validate TRZ physics against expected values and behaviors.
        
        Tests:
        1. f_TRZ = 0.1 → (1 + f_TRZ) = 1.1
        2. TRZ active when t_n < 0
        3. Pondermotive force direction (toward weaker field)
        4. COP > 1 only possible in TRZ
        """
        results = {}
        
        # Test 1: TRZ amplification factor
        factor, _ = self.compute_TRZ_inertia_factor()
        results['TRZ_factor'] = {
            'computed': factor,
            'expected': 1.1,
            'passed': abs(factor - 1.1) < 1e-10
        }
        
        # Test 2: TRZ detection
        is_active_neg, mode_neg = self.is_TRZ_active(-0.1)
        is_active_pos, mode_pos = self.is_TRZ_active(0.1)
        results['TRZ_detection'] = {
            't_n=-0.1': {'active': is_active_neg, 'mode': mode_neg},
            't_n=+0.1': {'active': is_active_pos, 'mode': mode_pos},
            'passed': is_active_neg and not is_active_pos
        }
        
        # Test 3: Pondermotive force direction
        F_p, _ = self.compute_pondermotive_force(1e9, 1e6)  # 1 GHz, positive gradient
        results['pondermotive'] = {
            'F_p': F_p,
            'direction': 'toward weaker field' if F_p < 0 else 'toward stronger field',
            'passed': F_p < 0  # Should be negative for positive gradient
        }
        
        # Test 4: COP classification
        COP_sub, class_sub, _ = self.compute_COP(90, 100)  # 0.9
        COP_unity, class_unity, _ = self.compute_COP(100, 100)  # 1.0
        COP_super, class_super, _ = self.compute_COP(110, 100)  # 1.1
        results['COP_classification'] = {
            'COP=0.9': {'COP': COP_sub, 'class': class_sub},
            'COP=1.0': {'COP': COP_unity, 'class': class_unity},
            'COP=1.1': {'COP': COP_super, 'class': class_super},
            'passed': COP_sub < 1.0 and COP_super > 1.0
        }
        
        # Test 5: Negentropic efficiency
        eta_active, _ = self.compute_negentropic_efficiency(-0.5)
        eta_inactive, _ = self.compute_negentropic_efficiency(0.5)
        results['negentropic_efficiency'] = {
            't_n=-0.5': eta_active,
            't_n=+0.5': eta_inactive,
            'passed': eta_active > 0 and eta_inactive == 0
        }
        
        # Overall pass/fail
        all_passed = all(r.get('passed', True) for r in results.values())
        results['overall'] = 'PASS' if all_passed else 'FAIL'
        
        return results
    
