# CGM METAL RETENTION MODEL (Drawing 31)
# ═══════════════════════════════════════════════════════════════════════════════

class CGMMetalRetentionModel:
    """
    Circumgalactic Medium (CGM) Metal Retention Model
    
    Models metal distribution between disk, CGM, and IGM based on
    AGN feedback and SMBH properties.
    
    KEY EQUATIONS (Drawing 31 - Sanchez et al. 2023):
    ─────────────────────────────────────────────────────────────────────────────
    
    1. Metal Retention Fraction:
       f_Z = (M_Z,disk_gas + M_Z,disk_stars) / M_Z,formed
       
       Where:
       - M_Z,disk_gas: Metals in disk gas at z=0
       - M_Z,disk_stars: Metals in disk stars at z=0
       - M_Z,formed: Total metals ever formed
    
    2. CGM Baryon Fraction:
       f_CGM = M_CGM / M_vir
       
       Where:
       - M_CGM: Baryonic mass in CGM
       - M_vir: Virial mass of halo
    
    3. AGN Feedback Modulation:
       Metal redistribution rate ∝ Ug4 × (1 + f_feedback)
       
       Over-massive SMBHs (ΔM_BH > 0): Enhanced metal ejection
       Under-massive SMBHs (ΔM_BH < 0): Metals retained in disk
    
    UQFF INTEGRATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    [SCm] expulsion from SMBH drives metal redistribution:
    - Enhanced [SCm] activity → metals driven to CGM
    - [UA] string interactions → energy transfer to gas
    - TRZ effects → negentropic reordering of metal distribution
    """
    
    def __init__(self):
        """Initialize CGM Metal Retention Model."""
        # Reference fractions from ROMULUS25 (Drawing 31)
        self.f_Z_halo_overmassive = CONSTANTS.get('f_Z_halo_overmassive', 0.89)
        self.f_Z_halo_undermassive = CONSTANTS.get('f_Z_halo_undermassive', 0.85)
        self.f_Z_disk_starforming = CONSTANTS.get('f_Z_disk_starforming', 0.73)
        self.f_Z_disk_quenched = CONSTANTS.get('f_Z_disk_quenched', 0.51)
        self.f_CGM_typical = CONSTANTS.get('f_CGM_typical', 0.15)
        
        # Feedback parameters
        self.f_feedback_per_dex = CONSTANTS.get('f_feedback_per_dex', 0.1)
        
        # Solar mass
        self.M_sun = CONSTANTS.get('M_sun', 1.989e30)
    
    def compute_metal_retention(self, M_Z_disk_gas: float, M_Z_disk_stars: float,
                                M_Z_formed: float) -> Tuple[float, str]:
        """
        Compute metal retention fraction.
        
        f_Z = (M_Z,disk_gas + M_Z,disk_stars) / M_Z,formed
        
        Args:
            M_Z_disk_gas: Metals in disk gas (M_☉)
            M_Z_disk_stars: Metals in disk stars (M_☉)
            M_Z_formed: Total metals formed (M_☉)
        
        Returns:
            f_Z: Metal retention fraction (0 to 1)
            steps: Derivation string
        """
        if M_Z_formed <= 0:
            return 0.0, "Error: M_Z,formed must be positive"
        
        M_Z_retained = M_Z_disk_gas + M_Z_disk_stars
        f_Z = M_Z_retained / M_Z_formed
        
        M_Z_ejected = M_Z_formed - M_Z_retained
        f_Z_ejected = M_Z_ejected / M_Z_formed
        
        steps = f"""Metal Retention Fraction Calculation:
═══════════════════════════════════════════════════════════════════════════════
Inputs:
  M_Z,disk_gas = {M_Z_disk_gas:.4e} M_☉
  M_Z,disk_stars = {M_Z_disk_stars:.4e} M_☉
  M_Z,formed = {M_Z_formed:.4e} M_☉

Formula:
  f_Z = (M_Z,disk_gas + M_Z,disk_stars) / M_Z,formed

Calculation:
  M_Z,retained = {M_Z_disk_gas:.4e} + {M_Z_disk_stars:.4e}
               = {M_Z_retained:.4e} M_☉
  
  f_Z = {M_Z_retained:.4e} / {M_Z_formed:.4e}
      = {f_Z:.4f}

Metal Budget:
  f_Z (retained) = {f_Z:.4f} = {f_Z*100:.1f}%
  f_Z (ejected) = {f_Z_ejected:.4f} = {f_Z_ejected*100:.1f}%
  
  M_Z,ejected = {M_Z_ejected:.4e} M_☉ (to CGM/IGM)

Comparison with ROMULUS25:
  Star-forming disks: f_Z ≈ {self.f_Z_disk_starforming}
  Quenched disks: f_Z ≈ {self.f_Z_disk_quenched}
  This system: f_Z = {f_Z:.4f}
═══════════════════════════════════════════════════════════════════════════════
"""
        return f_Z, steps
    
    def compute_CGM_baryon_fraction(self, M_CGM: float, M_vir: float) -> Tuple[float, str]:
        """
        Compute CGM baryon fraction.
        
        f_CGM = M_CGM / M_vir
        
        Args:
            M_CGM: Baryonic mass in CGM (M_☉)
            M_vir: Virial mass of halo (M_☉)
        
        Returns:
            f_CGM: CGM baryon fraction
            steps: Derivation string
        """
        if M_vir <= 0:
            return 0.0, "Error: M_vir must be positive"
        
        f_CGM = M_CGM / M_vir
        
        # Cosmic baryon fraction for comparison
        f_b_cosmic = 0.157  # Planck 2018
        
        steps = f"""CGM Baryon Fraction Calculation:
═══════════════════════════════════════════════════════════════════════════════
Inputs:
  M_CGM = {M_CGM:.4e} M_☉
  M_vir = {M_vir:.4e} M_☉

Formula:
  f_CGM = M_CGM / M_vir

Calculation:
  f_CGM = {M_CGM:.4e} / {M_vir:.4e}
        = {f_CGM:.4f}

Comparison:
  Cosmic baryon fraction f_b = {f_b_cosmic:.3f} (Planck 2018)
  Typical CGM fraction: {self.f_CGM_typical:.3f}
  This system: f_CGM = {f_CGM:.4f}
  
  {'CGM fraction above typical - enhanced metal content' if f_CGM > self.f_CGM_typical else 'CGM fraction below typical - metals in disk or ejected'}
═══════════════════════════════════════════════════════════════════════════════
"""
        return f_CGM, steps
    
    def compute_AGN_metal_redistribution(self, Delta_M_BH_dex: float, 
                                         M_Z_disk: float, t: float = 0.0) -> Tuple[float, float, str]:
        """
        Compute AGN-driven metal redistribution.
        
        Rate of metal transfer from disk to CGM based on SMBH mass deviation.
        
        Args:
            Delta_M_BH_dex: SMBH mass deviation (dex)
            M_Z_disk: Current disk metal mass (M_☉)
            t: Time (Myr)
        
        Returns:
            dM_Z_dt: Metal transfer rate (M_☉/Myr)
            f_transferred: Fraction transferred per Gyr
            steps: Derivation string
        """
        # Feedback factor
        f_feedback = abs(Delta_M_BH_dex) * self.f_feedback_per_dex
        
        # Base timescale (dynamical time ~ 100 Myr for typical galaxy)
        tau_dyn = 100.0  # Myr
        
        # Transfer rate enhanced by feedback
        # Positive ΔM_BH → enhanced outward transfer
        direction = 1.0 if Delta_M_BH_dex > 0 else -1.0
        dM_Z_dt = direction * M_Z_disk * f_feedback / tau_dyn
        
        # Fraction transferred per Gyr
        f_transferred = abs(dM_Z_dt * 1000.0 / M_Z_disk) if M_Z_disk > 0 else 0
        
        steps = f"""AGN-Driven Metal Redistribution:
═══════════════════════════════════════════════════════════════════════════════
Inputs:
  ΔM_BH = {Delta_M_BH_dex:+.4f} dex
  M_Z,disk = {M_Z_disk:.4e} M_☉
  t = {t:.1f} Myr

Step 1: Compute feedback factor:
  f_feedback = |ΔM_BH| × {self.f_feedback_per_dex}/dex
             = |{Delta_M_BH_dex:+.4f}| × {self.f_feedback_per_dex}
             = {f_feedback:.4f}

Step 2: Compute transfer rate:
  τ_dyn = {tau_dyn} Myr (dynamical timescale)
  Direction = {'outward (to CGM)' if dM_Z_dt > 0 else 'inward (cooling)'}
  
  dM_Z/dt = {'+' if Delta_M_BH_dex > 0 else '-'}M_Z,disk × f_feedback / τ_dyn
          = {dM_Z_dt:+.4e} M_☉/Myr

Step 3: Long-term transfer:
  f_transferred = |dM_Z/dt| × 1000 Myr / M_Z,disk
                = {f_transferred:.4f} per Gyr
                = {f_transferred*100:.1f}% of disk metals per Gyr

UQFF Interpretation:
  • {'Over-massive SMBH: Enhanced [SCm] expulsion drives metals outward' if Delta_M_BH_dex > 0 else 'Under-massive SMBH: Reduced feedback allows metal cooling/retention'}
  • AGN feedback flattens metallicity gradients
  • CGM metal content increases with SMBH mass excess
═══════════════════════════════════════════════════════════════════════════════
"""
        return dM_Z_dt, f_transferred, steps
    
    def validate_CGM_model(self) -> Tuple[bool, list, str]:
        """
        Validate CGM Metal Retention model.
        """
        tests = []
        
        # Test 1: Metal retention fraction calculation
        f_Z, _ = self.compute_metal_retention(1e8, 5e8, 1e9)
        tests.append({
            'name': 'Metal retention fraction',
            'f_Z': f_Z,
            'expected': 0.6,  # (1+5)/10
            'passed': abs(f_Z - 0.6) < 0.001
        })
        
        # Test 2: CGM baryon fraction
        f_CGM, _ = self.compute_CGM_baryon_fraction(1.5e11, 1e12)
        tests.append({
            'name': 'CGM baryon fraction',
            'f_CGM': f_CGM,
            'expected': 0.15,
            'passed': abs(f_CGM - 0.15) < 0.001
        })
        
        # Test 3: AGN redistribution direction
        dM_dt_over, _, _ = self.compute_AGN_metal_redistribution(1.0, 1e9)
        dM_dt_under, _, _ = self.compute_AGN_metal_redistribution(-1.0, 1e9)
        tests.append({
            'name': 'AGN redistribution direction',
            'overmassive': dM_dt_over,
            'undermassive': dM_dt_under,
            'passed': dM_dt_over > 0 and dM_dt_under < 0
        })
        
        all_passed = all(t['passed'] for t in tests)
        
        summary = f"""CGM METAL RETENTION MODEL VALIDATION
════════════════════════════════════════════════════════════════════════════════
TEST RESULTS:
────────────────────────────────────────────────────────────────────────────────
1. Metal retention fraction:    {'✓ PASS' if tests[0]['passed'] else '✗ FAIL'}
   f_Z = {tests[0]['f_Z']:.4f} (expected {tests[0]['expected']})

2. CGM baryon fraction:         {'✓ PASS' if tests[1]['passed'] else '✗ FAIL'}
   f_CGM = {tests[1]['f_CGM']:.4f} (expected {tests[1]['expected']})

3. AGN redistribution:          {'✓ PASS' if tests[2]['passed'] else '✗ FAIL'}
   Over-massive: dM/dt = {tests[2]['overmassive']:+.2e} M_☉/Myr (outward)
   Under-massive: dM/dt = {tests[2]['undermassive']:+.2e} M_☉/Myr (inward)

────────────────────────────────────────────────────────────────────────────────
SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed
────────────────────────────────────────────────────────────────────────────────
{'ALL TESTS PASSED ✓' if all_passed else 'SOME TESTS FAILED ✗'}
════════════════════════════════════════════════════════════════════════════════
"""
        return all_passed, tests, summary


# Global CGM Metal Retention Model instance
CGM_MODEL = CGMMetalRetentionModel()


