# CGM BARYON FRACTION MODEL (Drawing 31, Pages 12-13)
# ═══════════════════════════════════════════════════════════════════════════════

class CGMBaryonFractionModel:
    """
    CGM Baryon Fraction Model (Drawing 31: Sanchez et al. Paper)
    
    From the Universal Inertia document: The CGM baryon fraction measures
    the fraction of baryons in the circumgalactic medium relative to the
    virial mass. Over-massive SMBHs reduce f_CGM through AGN feedback.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    f_CGM = M_CGM / M_vir
    
    Where:
        M_CGM: Mass of baryons in circumgalactic medium (kg)
        M_vir: Virial mass of galaxy (kg)
    
    DEPENDENCE ON ΔM_BH:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Over-massive SMBHs (ΔM_BH > 0): Lower f_CGM (AGN evacuates baryons)
    - Under-massive SMBHs (ΔM_BH < 0): Higher f_CGM (baryons retained)
    
    TYPICAL VALUES:
    ─────────────────────────────────────────────────────────────────────────────
    
    f_CGM ≈ 0.05 - 0.15 for Milky Way-mass galaxies
    Cosmic baryon fraction: Ω_b/Ω_m ≈ 0.16
    """
    
    def __init__(self):
        """Initialize CGM Baryon Fraction Model."""
        # Cosmic baryon fraction
        self.cosmic_baryon_fraction = 0.16  # Ω_b/Ω_m from Planck
        
        # Typical f_CGM range
        self.f_CGM_typical = 0.10  # Typical for MW-mass galaxy
        
        # AGN feedback reduction factor
        self.AGN_reduction_per_dex = 0.02  # ≈20% reduction per dex offset
    
    def compute_baryon_fraction(self, M_CGM: float, M_vir: float) -> Tuple[float, str]:
        """
        Compute CGM baryon fraction.
        
        f_CGM = M_CGM / M_vir
        
        Args:
            M_CGM: CGM baryon mass (kg)
            M_vir: Virial mass (kg)
        
        Returns:
            f_CGM: CGM baryon fraction
            steps: Derivation string
        """
        f_CGM = M_CGM / M_vir
        
        # Compare to cosmic baryon fraction
        f_cosmic = self.cosmic_baryon_fraction
        retention = f_CGM / f_cosmic
        
        steps = f"""
    CGM BARYON FRACTION
    ══════════════════════════════════════════════════════════════════
    
    f_CGM = M_CGM / M_vir
    
    PARAMETERS:
        M_CGM = {M_CGM:.4e} kg
        M_vir = {M_vir:.4e} kg
    
    CALCULATION:
        f_CGM = {M_CGM:.4e} / {M_vir:.4e}
              = {f_CGM:.4f}
    
    COMPARISON TO COSMIC:
        Cosmic baryon fraction (Ω_b/Ω_m) = {f_cosmic:.4f}
        CGM retention = f_CGM / f_cosmic = {retention:.2%}
    
    INTERPRETATION:
        {'CGM retains most baryons' if retention > 0.5 else
         'AGN has expelled significant baryons' if retention < 0.3 else
         'Moderate baryon retention'}
    ══════════════════════════════════════════════════════════════════"""
        
        return f_CGM, steps
    
    def compute_f_CGM_from_delta_MBH(self, delta_M_BH: float,
                                      f_CGM_baseline: float = None) -> Tuple[float, str]:
        """
        Compute CGM baryon fraction given M-σ offset.
        
        f_CGM = f_CGM_baseline × (1 - AGN_reduction × ΔM_BH) for ΔM_BH > 0
        
        Args:
            delta_M_BH: M-σ offset (dex)
            f_CGM_baseline: Baseline f_CGM (defaults to 0.10)
        
        Returns:
            f_CGM: CGM baryon fraction
            steps: Derivation string
        """
        f_CGM_baseline = f_CGM_baseline if f_CGM_baseline is not None else self.f_CGM_typical
        
        # Over-massive reduces f_CGM, under-massive increases slightly
        if delta_M_BH > 0:
            reduction = self.AGN_reduction_per_dex * delta_M_BH
            f_CGM = f_CGM_baseline * (1 - reduction)
        else:
            # Under-massive: slight increase (less feedback)
            increase = 0.01 * abs(delta_M_BH)
            f_CGM = f_CGM_baseline * (1 + increase)
        
        f_CGM = max(0, min(f_CGM, 1))  # Clamp to [0, 1]
        
        steps = f"""
    CGM BARYON FRACTION FROM M-σ OFFSET
    ══════════════════════════════════════════════════════════════════
    
    PARAMETERS:
        ΔM_BH = {delta_M_BH:.2f} dex
        f_CGM_baseline = {f_CGM_baseline:.4f}
        AGN reduction = {self.AGN_reduction_per_dex:.2f} per dex
    
    CALCULATION:
        {'Over-massive SMBH → Reduces f_CGM' if delta_M_BH > 0 else
         'Under-massive SMBH → Increases f_CGM' if delta_M_BH < 0 else
         'On M-σ relation → Baseline f_CGM'}
        
        f_CGM = {f_CGM:.4f}
    
    PHYSICAL INTERPRETATION:
        {'Strong AGN feedback expels baryons from CGM' if delta_M_BH > 0 else
         'Weak AGN feedback allows baryon accumulation' if delta_M_BH < 0 else
         'Balanced baryon budget'}
    ══════════════════════════════════════════════════════════════════"""
        
        return f_CGM, steps
    
    def compute_metal_retention_fraction(self, f_Z_disk: float,
                                          f_Z_CGM: float) -> Tuple[float, str]:
        """
        Compute total metal retention fraction.
        
        f_Z_total = f_Z_disk + f_Z_CGM
        
        Args:
            f_Z_disk: Fraction of metals retained in disk
            f_Z_CGM: Fraction of metals in CGM
        
        Returns:
            f_Z_total: Total metal retention
            steps: Derivation string
        """
        f_Z_total = f_Z_disk + f_Z_CGM
        
        steps = f"""
    METAL RETENTION FRACTION
    ══════════════════════════════════════════════════════════════════
    
    f_Z_total = f_Z_disk + f_Z_CGM
    
    PARAMETERS:
        f_Z_disk = {f_Z_disk:.4f} (fraction in disk)
        f_Z_CGM = {f_Z_CGM:.4f} (fraction in CGM)
    
    CALCULATION:
        f_Z_total = {f_Z_disk:.4f} + {f_Z_CGM:.4f}
                  = {f_Z_total:.4f}
    
    REMAINING METALS:
        Fraction in IGM = 1 - f_Z_total = {1 - f_Z_total:.4f}
    
    From Drawing 31: SMBHs primarily drive metals into CGM, not IGM
    ══════════════════════════════════════════════════════════════════"""
        
        return f_Z_total, steps
    
    def validate_model(self) -> Tuple[bool, list, str]:
        """Validate CGM Baryon Fraction Model."""
        tests = []
        
        # Test 1: f_CGM = M_CGM / M_vir
        M_CGM = 1e11 * 2e30  # 10^11 M_sun
        M_vir = 1e12 * 2e30  # 10^12 M_sun
        f_CGM, _ = self.compute_baryon_fraction(M_CGM, M_vir)
        tests.append({
            'name': 'f_CGM = M_CGM / M_vir',
            'f_CGM': f_CGM,
            'passed': abs(f_CGM - 0.1) < 1e-10
        })
        
        # Test 2: Over-massive reduces f_CGM
        f_CGM_over, _ = self.compute_f_CGM_from_delta_MBH(1.0)
        tests.append({
            'name': 'Over-massive reduces f_CGM',
            'f_CGM': f_CGM_over,
            'passed': f_CGM_over < self.f_CGM_typical
        })
        
        # Test 3: Under-massive increases f_CGM
        f_CGM_under, _ = self.compute_f_CGM_from_delta_MBH(-1.0)
        tests.append({
            'name': 'Under-massive increases f_CGM',
            'f_CGM': f_CGM_under,
            'passed': f_CGM_under > self.f_CGM_typical
        })
        
        # Test 4: Total metal retention
        f_Z_total, _ = self.compute_metal_retention_fraction(0.6, 0.3)
        tests.append({
            'name': 'f_Z_total = f_Z_disk + f_Z_CGM',
            'f_Z_total': f_Z_total,
            'passed': abs(f_Z_total - 0.9) < 1e-10
        })
        
        all_passed = all(t['passed'] for t in tests)
        
        summary = f"""CGM BARYON FRACTION MODEL VALIDATION
════════════════════════════════════════════════════════════════════════════════
TEST RESULTS:
────────────────────────────────────────────────────────────────────────────────
1. f_CGM = M_CGM / M_vir:          {'✓ PASS' if tests[0]['passed'] else '✗ FAIL'}
   f_CGM = {tests[0]['f_CGM']:.4f}

2. Over-massive reduces f_CGM:     {'✓ PASS' if tests[1]['passed'] else '✗ FAIL'}
   f_CGM = {tests[1]['f_CGM']:.4f} < 0.10

3. Under-massive increases f_CGM:  {'✓ PASS' if tests[2]['passed'] else '✗ FAIL'}
   f_CGM = {tests[2]['f_CGM']:.4f} > 0.10

4. f_Z_total = f_Z_disk + f_Z_CGM: {'✓ PASS' if tests[3]['passed'] else '✗ FAIL'}
   f_Z_total = {tests[3]['f_Z_total']:.4f}

────────────────────────────────────────────────────────────────────────────────
SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed
────────────────────────────────────────────────────────────────────────────────
{'ALL TESTS PASSED ✓' if all_passed else 'SOME TESTS FAILED ✗'}
════════════════════════════════════════════════════════════════════════════════
"""
        return all_passed, tests, summary


# Global CGM Baryon Fraction Model instance
CGM_BARYON_MODEL = CGMBaryonFractionModel()


# ═══════════════════════════════════════════════════════════════════════════════
# COMPLETE UNIFIED FIELD MODEL (Comprehensive F_U)
# ═══════════════════════════════════════════════════════════════════════════════

class CompleteUnifiedFieldModel:
    """
    Complete Unified Field Model - Full F_U Equation
    
    From the Universal Inertia document: The complete unified field equation
    incorporating all universal forces (Ug, Um, Ub, Ui) with Aether dynamics,
    metric contributions, and reactor energy terms.
    
    COMPLETE UNIFIED FIELD EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    F_U = Σᵢ[kᵢ × Ugᵢ - βᵢ × Ugᵢ × Ωg × M_bh/d_g × E_react]    (Gravity terms)
        + Σⱼ[μⱼ/rⱼ × (1 - e^(-γt) × cos(πt_n)) × φ̂ⱼ]          (Magnetic strings)
        + (g_μν + η × T_s^μν)                                  (Metric + Aether)
        - Σᵢ[λᵢ × Uᵢ × E_react]                                (Inertia damping)
    
    COMPONENTS:
    ─────────────────────────────────────────────────────────────────────────────
    
    1. GRAVITY BLOCK: Ug1 (internal dipole), Ug2 (outer bubble), 
                       Ug3 (magnetic disk), Ug4 (star-BH interaction)
    
    2. MAGNETIC BLOCK: Um contributions from magnetic strings
    
    3. METRIC BLOCK: Spacetime metric g_μν with Aether stress-energy T_s^μν
    
    4. INERTIA BLOCK: Ui contributions with reactor energy coupling
    
    OUTPUTS UNIFIED ENERGY DENSITY in J/m³
    """
    
    def __init__(self):
        """Initialize Complete Unified Field Model."""
        # Coupling constants
        self.k = [1.0, 1.0, 1.0, 1.0]  # k1-k4 for Ug1-Ug4
        self.beta = [0.01, 0.01, 0.01, 0.01]  # β for reactor coupling
        self.mu = [1.0]  # μ for magnetic strings
        self.lambda_i = [1.0]  # λ for inertia
        
        # Physical parameters
        self.gamma = 0.01  # day⁻¹
        self.eta = 1e-40  # Aether coupling (very small)
        
        # Reference values
        self.G = CONSTANTS.get('G', 6.674e-11)
        self.c = CONSTANTS.get('c_light', 2.998e8)
    
    def compute_gravity_block(self, Ug_values: list, Omega_g: float = 1.0,
                               M_bh: float = 4e6 * 2e30, d_g: float = 2.55e20,
                               E_react: float = 1e10) -> Tuple[float, str]:
        """
        Compute gravity block of unified field.
        
        F_gravity = Σᵢ[kᵢ × Ugᵢ - βᵢ × Ugᵢ × Ωg × M_bh/d_g × E_react]
        
        Args:
            Ug_values: List of [Ug1, Ug2, Ug3, Ug4] in J/m³
            Omega_g: Galactic rotation factor
            M_bh: Black hole mass (kg)
            d_g: Galactic distance (m)
            E_react: Reactor energy (J)
        
        Returns:
            F_gravity: Gravity contribution (J/m³)
            steps: Derivation string
        """
        F_gravity = 0.0
        terms = []
        
        for i, Ug in enumerate(Ug_values):
            primary = self.k[i] * Ug
            reactor_coupling = self.beta[i] * Ug * Omega_g * M_bh / d_g * E_react
            term = primary - reactor_coupling
            F_gravity += term
            terms.append((i+1, Ug, primary, reactor_coupling, term))
        
        steps = f"""
    GRAVITY BLOCK: F_gravity = Σᵢ[kᵢ×Ugᵢ - βᵢ×Ugᵢ×Ωg×M_bh/d_g×E_react]
    ══════════════════════════════════════════════════════════════════
    
    PARAMETERS:
        Ωg = {Omega_g}
        M_bh = {M_bh:.4e} kg
        d_g = {d_g:.4e} m
        E_react = {E_react:.4e} J
    
    GRAVITY TERMS:
    ──────────────────────────────────────────────────────────────────
"""
        for i, Ug, primary, reactor, term in terms:
            steps += f"    Ug{i}: {Ug:.4e} → k×Ug = {primary:.4e}, reactor = {reactor:.4e}, net = {term:.4e}\n"
        
        steps += f"""
    ──────────────────────────────────────────────────────────────────
    F_gravity = {F_gravity:.4e} J/m³
    ══════════════════════════════════════════════════════════════════"""
        
        return F_gravity, steps
    
    def compute_magnetic_block(self, r_values: list, t: float = 0.0,
                                t_n: float = 0.0) -> Tuple[float, str]:
        """
        Compute magnetic string block.
        
        F_magnetic = Σⱼ[μⱼ/rⱼ × (1 - e^(-γt) × cos(πt_n)) × φ̂]
        
        Args:
            r_values: List of radial distances (m)
            t: Time (days)
            t_n: Negative time parameter
        
        Returns:
            F_magnetic: Magnetic contribution (dimensionless for direction)
            steps: Derivation string
        """
        time_factor = 1 - np.exp(-self.gamma * t) * np.cos(np.pi * t_n)
        
        F_magnetic = 0.0
        for j, r in enumerate(r_values):
            mu_j = self.mu[0] if len(self.mu) == 1 else self.mu[j]
            F_magnetic += mu_j / r * time_factor
        
        steps = f"""
    MAGNETIC BLOCK: F_magnetic = Σⱼ[μⱼ/rⱼ × (1 - e^(-γt)×cos(πt_n))]
    ══════════════════════════════════════════════════════════════════
    
    PARAMETERS:
        γ = {self.gamma} day⁻¹
        t = {t} days
        t_n = {t_n}
        Time factor = 1 - e^(-{self.gamma}×{t}) × cos(π×{t_n})
                    = {time_factor:.6f}
    
    MAGNETIC STRING CONTRIBUTIONS:
    ──────────────────────────────────────────────────────────────────
"""
        for j, r in enumerate(r_values):
            steps += f"    String {j+1}: r = {r:.4e} m → contribution = {self.mu[0]/r * time_factor:.4e}\n"
        
        steps += f"""
    ──────────────────────────────────────────────────────────────────
    F_magnetic = {F_magnetic:.4e}
    ══════════════════════════════════════════════════════════════════"""
        
        return F_magnetic, steps
    
    def compute_metric_block(self, g_mu_nu: float = -1.0,
                              T_s_mu_nu: float = 1e-23) -> Tuple[float, str]:
        """
        Compute metric + Aether block.
        
        F_metric = g_μν + η × T_s^μν
        
        Args:
            g_mu_nu: Metric component (typically -1 to +1)
            T_s_mu_nu: Aether stress-energy component (J/m³)
        
        Returns:
            F_metric: Metric contribution
            steps: Derivation string
        """
        F_metric = g_mu_nu + self.eta * T_s_mu_nu
        
        steps = f"""
    METRIC BLOCK: F_metric = g_μν + η × T_s^μν
    ══════════════════════════════════════════════════════════════════
    
    PARAMETERS:
        g_μν = {g_mu_nu} (metric component)
        η = {self.eta:.4e} (Aether coupling)
        T_s^μν = {T_s_mu_nu:.4e} J/m³ (Aether stress-energy)
    
    CALCULATION:
        F_metric = {g_mu_nu} + {self.eta:.4e} × {T_s_mu_nu:.4e}
                 = {F_metric:.10f}
    
    NOTE: Aether contribution is extremely small (η ~ 10⁻⁴⁰)
    ══════════════════════════════════════════════════════════════════"""
        
        return F_metric, steps
    
    def compute_inertia_block(self, Ui: float, E_react: float = 1e10) -> Tuple[float, str]:
        """
        Compute inertia damping block.
        
        F_inertia = -Σᵢ[λᵢ × Uᵢ × E_react]
        
        Args:
            Ui: Universal Inertia
            E_react: Reactor energy (J)
        
        Returns:
            F_inertia: Inertia contribution (negative = damping)
            steps: Derivation string
        """
        F_inertia = -self.lambda_i[0] * Ui * E_react
        
        steps = f"""
    INERTIA BLOCK: F_inertia = -Σᵢ[λᵢ × Uᵢ × E_react]
    ══════════════════════════════════════════════════════════════════
    
    PARAMETERS:
        λ = {self.lambda_i[0]}
        Ui = {Ui:.4e}
        E_react = {E_react:.4e} J
    
    CALCULATION:
        F_inertia = -{self.lambda_i[0]} × {Ui:.4e} × {E_react:.4e}
                  = {F_inertia:.4e}
    
    INTERPRETATION:
        Negative value = damping effect
        Inertia opposes changes, stabilizing the system
    ══════════════════════════════════════════════════════════════════"""
        
        return F_inertia, steps
    
    def compute_complete_F_U(self, Ug_values: list = None,
                               r_values: list = None,
                               Ui: float = 2.75e-7,
                               **kwargs) -> Tuple[float, str]:
        """
        Compute complete unified field F_U.
        
        Args:
            Ug_values: [Ug1, Ug2, Ug3, Ug4] in J/m³
            r_values: Magnetic string radii (m)
            Ui: Universal Inertia
            **kwargs: Additional parameters
        
        Returns:
            F_U: Complete unified field (J/m³)
            steps: Derivation string
        """
        Ug_values = Ug_values if Ug_values is not None else [1e-10, 1e-11, 1e-12, 1e-13]
