# OORT CLOUD BOUNDARY MODEL
# ═══════════════════════════════════════════════════════════════════════════════

class OortCloudBoundaryModel:
    """
    Oort Cloud Boundary Model - Outermost Solar System
    
    From the document: The Oort Cloud marks the practical boundary of solar
    control, with objects at ~100,000 AU still gravitationally bound.
    
    STRUCTURE:
    ─────────────────────────────────────────────────────────────────────────────
    
    Inner Oort Cloud: 2,000 - 20,000 AU
    Outer Oort Cloud: 20,000 - 100,000 AU (possibly 200,000 AU)
    
    COMET ORIGINS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Long-period comets (e.g., Hale-Bopp, C/2021 O3) have orbits tracing
    back to 50,000+ AU, suggesting Oort Cloud origins.
    
    PERTURBATION SOURCES:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Galactic tidal forces
    - Passing stars (e.g., Scholz's Star at 0.8 ly, 70,000 years ago)
    - Giant molecular clouds
    
    Objects beyond ~100,000-200,000 AU drift into interstellar space.
    """
    
    def __init__(self):
        """Initialize Oort Cloud Boundary Model."""
        # Distance units
        self.AU = 1.496e11  # m
        self.ly = 9.461e15  # m
        
        # Oort Cloud boundaries (AU)
        self.inner_oort_min = 2000
        self.inner_oort_max = 20000
        self.outer_oort_min = 20000
        self.outer_oort_max = 100000  # Conservative
        self.outer_oort_max_liberal = 200000  # Some models
        
        # Notable comets
        self.long_period_comets = {
            'Hale-Bopp': {'period_years': 2520, 'aphelion_AU': 370},
            'Hyakutake': {'period_years': 70000, 'aphelion_AU': 1700},
            'C/2021 O3 PANSTARRS': {'period_years': 'hyperbolic', 'aphelion_AU': 'ejected'},
            'C/1995 O1': {'period_years': 2533, 'aphelion_AU': 371}
        }
        
        # Perturbation events
        self.stellar_flybys = {
            'Scholz_Star': {'distance_ly': 0.8, 'time_kya': 70}
        }
    
    def compute_orbital_period(self, a_AU: float) -> Tuple[float, str]:
        """
        Compute orbital period for object at semi-major axis a.
        
        T = a^(3/2) years (Kepler's 3rd law, with a in AU)
        
        Args:
            a_AU: Semi-major axis (AU)
        
        Returns:
            T_years: Orbital period (years)
            steps: Derivation string
        """
        T_years = a_AU**(3/2)
        T_Myr = T_years / 1e6
        
        steps = f"""
    ORBITAL PERIOD IN OORT CLOUD
    ══════════════════════════════════════════════════════════════════
    
    Kepler's 3rd Law: T = a^(3/2) (for a in AU, T in years)
    
    PARAMETERS:
        Semi-major axis a = {a_AU:,.0f} AU
    
    CALCULATION:
        T = ({a_AU:,.0f})^(3/2)
          = {T_years:,.0f} years
          = {T_Myr:.3f} million years
    
    CONTEXT:
        Inner Oort (2,000 AU): T = {2000**(3/2):,.0f} years
        Outer Oort (100,000 AU): T = {100000**(3/2):,.0f} years = {100000**(3/2)/1e6:.1f} Myr
    ══════════════════════════════════════════════════════════════════"""
        
        return T_years, steps
    
    def classify_object(self, distance_AU: float) -> Tuple[str, str]:
        """
        Classify object by distance from Sun.
        
        Args:
            distance_AU: Distance from Sun (AU)
        
        Returns:
            region: Classification
            binding: Bound status
        """
        if distance_AU < 30:
            region = 'Planetary region'
        elif distance_AU < 50:
            region = 'Kuiper Belt'
        elif distance_AU < self.inner_oort_min:
            region = 'Scattered Disc / Extreme TNOs'
        elif distance_AU < self.inner_oort_max:
            region = 'Inner Oort Cloud'
        elif distance_AU < self.outer_oort_max:
            region = 'Outer Oort Cloud'
        elif distance_AU < self.outer_oort_max_liberal:
            region = 'Outer Oort Cloud (extended)'
        else:
            region = 'Beyond Oort Cloud / Interstellar'
        
        if distance_AU < self.outer_oort_max_liberal:
            binding = 'Gravitationally bound to Sun'
        else:
            binding = 'Marginally bound or unbound'
        
        return region, binding
    
    def compute_perturbation_effect(self, stellar_flyby: str = 'Scholz_Star') -> Tuple[float, str]:
        """
        Compute perturbation effect from stellar flyby.
        
        Args:
            stellar_flyby: Name of stellar flyby event
        
        Returns:
            affected_radius: Estimated radius of affected region (AU)
            steps: Description
        """
        if stellar_flyby not in self.stellar_flybys:
            return 0, "Unknown flyby"
        
        flyby = self.stellar_flybys[stellar_flyby]
        distance_ly = flyby['distance_ly']
        time_kya = flyby['time_kya']
        
        # Estimated affected region (within 10% of closest approach)
        distance_AU = distance_ly * self.ly / self.AU
        affected_radius = distance_AU * 0.1
        
        steps = f"""
    STELLAR FLYBY PERTURBATION
    ══════════════════════════════════════════════════════════════════
    
    EVENT: {stellar_flyby.replace('_', "'s ")}
    CLOSEST APPROACH: {distance_ly} light-years = {distance_AU:,.0f} AU
    TIME: {time_kya:,} thousand years ago
    
    PERTURBATION EFFECT:
        - Objects within ~{affected_radius:,.0f} AU of flyby path affected
        - Can eject comets into interstellar space
        - Can deflect comets inward (sends toward inner Solar System)
    
    From document: "Beyond 100,000-200,000 AU, the Sun's grip weakens,
    and objects drift into interstellar space"
    ══════════════════════════════════════════════════════════════════"""
        
        return affected_radius, steps
    
    def validate_model(self) -> Tuple[bool, list, str]:
        """Validate Oort Cloud Boundary Model."""
        tests = []
        
        # Test 1: Outer Oort at 100,000 AU
        tests.append({
            'name': 'Outer Oort max = 100,000 AU',
            'value': self.outer_oort_max,
            'passed': self.outer_oort_max == 100000
        })
        
        # Test 2: Orbital period at Oort scales
        T, _ = self.compute_orbital_period(100000)
        expected = 100000**(3/2)
        tests.append({
            'name': 'Kepler orbital period works',
            'T': T,
            'passed': abs(T - expected) < 1
        })
        
        # Test 3: Classification works
        region, binding = self.classify_object(50000)
        tests.append({
            'name': '50,000 AU = Outer Oort Cloud',
            'region': region,
            'passed': 'Outer Oort' in region
        })
        
        # Test 4: Long-period comets defined
        tests.append({
            'name': 'Long-period comets defined',
            'n_comets': len(self.long_period_comets),
            'passed': len(self.long_period_comets) >= 3
        })
        
        all_passed = all(t['passed'] for t in tests)
        
        summary = f"""OORT CLOUD BOUNDARY MODEL VALIDATION
════════════════════════════════════════════════════════════════════════════════
TEST RESULTS:
────────────────────────────────────────────────────────────────────────────────
1. Outer Oort max = 100,000 AU:    {'✓ PASS' if tests[0]['passed'] else '✗ FAIL'}
   Value = {tests[0]['value']:,} AU

2. Kepler orbital period:          {'✓ PASS' if tests[1]['passed'] else '✗ FAIL'}
   T(100,000 AU) = {tests[1]['T']:,.0f} years

3. 50,000 AU classification:       {'✓ PASS' if tests[2]['passed'] else '✗ FAIL'}
   Region: {tests[2]['region']}

4. Long-period comets defined:     {'✓ PASS' if tests[3]['passed'] else '✗ FAIL'}
   {tests[3]['n_comets']} comets

────────────────────────────────────────────────────────────────────────────────
SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed
────────────────────────────────────────────────────────────────────────────────
{'ALL TESTS PASSED ✓' if all_passed else 'SOME TESTS FAILED ✗'}
════════════════════════════════════════════════════════════════════════════════
"""
        return all_passed, tests, summary


# Global Oort Cloud Boundary Model instance
OORT_CLOUD_MODEL = OortCloudBoundaryModel()


