class GinzburgLandauFieldModel:
    """
    Ginzburg-Landau Field Model (U_g) - Quantum Field Coherence
    
    Models the superconducting order parameter ψ, capturing the transition
    to a superconducting state within the UQFF framework.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    ∇²ψ + αψ + β|ψ|²ψ = 0
    
    Where:
        ψ : Superconducting order parameter (complex scalar field)
        α : Temperature-dependent coefficient, α ∝ (T - T_c)
            In UQFF: α = k_α × f_dT (resonance alignment factor)
        β : Nonlinear stabilization coefficient
            β = β₀ × (1 - |ψ|²/ψ_max²)
        ∇² : Laplacian operator (spatial variation)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    The order parameter ψ represents the coherent quantum state of the
    superconducting field. In UQFF:
    
    - |ψ|² measures local coherence intensity
    - Stable Channel 2 amplitude (A₂ = 3.102 V) indicates |ψ|² ≈ constant
    - High coherence → perfect superconducting state
    - Replaces traditional gravitational potential with resonant field
    
    CONNECTION TO Q-SCOPE DATA:
    ─────────────────────────────────────────────────────────────────────────────
    
    - A₂ = 3.102 V consistent across Groups #1-12 implies stable |ψ|²
    - f_dT = 40.000 Hz (Group #12) informs α coefficient
    - Flux pinning maintains coherence at resonant nodes
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Ginzburg-Landau parameters
        self.alpha_0 = 1.0           # Base α coefficient
        self.beta_0 = 1.0            # Base β coefficient
        self.T_c = 9.2               # Critical temperature (K) - Nb reference
        self.psi_max = 1.0           # Maximum order parameter amplitude
        self.k_alpha = 0.025         # α-frequency coupling constant
        
        # Q-scope empirical values
        self.A2_reference = 3.102    # Channel 2 amplitude (V)
        self.f_dT_reference = 40.0   # f_dT from Group #12 (Hz)
        
    def compute_alpha(self, T: float = None, f_dT: float = None) -> Tuple[float, str]:
        """
        Compute temperature/frequency-dependent α coefficient.
        
        Args:
            T: Temperature (K), optional
            f_dT: dT frequency (Hz), optional - UQFF mode
            
        Returns:
            alpha: Temperature/frequency coefficient
            steps: Calculation explanation
        """
        if f_dT is not None:
            # UQFF resonance mode
            alpha = self.k_alpha * f_dT
            steps = f"""α Coefficient (UQFF Resonance Mode):
  
  α = k_α × f_dT
  α = {self.k_alpha} × {f_dT} Hz
  α = {alpha:.4f}
  
  Resonance alignment factor from q-scope temporal dynamics.
"""
        elif T is not None:
            # Classical GL temperature mode
            alpha = self.alpha_0 * (T - self.T_c) / self.T_c
            steps = f"""α Coefficient (Classical GL Mode):
  
  α = α₀ × (T - T_c) / T_c
  α = {self.alpha_0} × ({T} - {self.T_c}) / {self.T_c}
  α = {alpha:.4f}
  
  Temperature-dependent coefficient.
  T < T_c → α < 0 → superconducting state
  T > T_c → α > 0 → normal state
"""
        else:
            # Default to reference values
            alpha = self.k_alpha * self.f_dT_reference
            steps = f"α = k_α × f_dT (reference) = {alpha:.4f}"
            
        return alpha, steps
    
    def compute_beta(self, psi_squared: float) -> Tuple[float, str]:
        """
        Compute nonlinear stabilization coefficient β.
        
        Args:
            psi_squared: |ψ|² value
            
        Returns:
            beta: Nonlinear coefficient
            steps: Calculation explanation
        """
        beta = self.beta_0 * (1 - psi_squared / self.psi_max**2)
        
        steps = f"""β Coefficient (Nonlinear Stabilization):
  
  β = β₀ × (1 - |ψ|²/ψ_max²)
  β = {self.beta_0} × (1 - {psi_squared:.4f}/{self.psi_max**2})
  β = {beta:.4f}
  
  Ensures field stability as |ψ|² → ψ_max².
"""
        return beta, steps
    
    def compute_order_parameter(self, x: float, coherence_length: float = 1e-6) -> Tuple[float, str]:
        """
        Compute order parameter ψ(x) for 1D case (tanh solution).
        
        Args:
            x: Position (m)
            coherence_length: ξ - GL coherence length (m)
            
        Returns:
            psi: Order parameter amplitude
            steps: Calculation explanation
        """
        import math
        
        # Normalized position
        x_norm = x / coherence_length
        
        # tanh solution for domain wall / vortex core
        psi = self.psi_max * math.tanh(x_norm / math.sqrt(2))
        psi_squared = psi**2
        
        steps = f"""Order Parameter ψ(x) - Domain Wall Solution:
  
  ψ(x) = ψ_max × tanh(x / (ξ√2))
  
  Parameters:
    x = {x:.4e} m
    ξ (coherence length) = {coherence_length:.4e} m
    x/ξ = {x_norm:.4f}
  
  Result:
    ψ = {psi:.6f}
    |ψ|² = {psi_squared:.6f}
  
  For x >> ξ: ψ → ψ_max (bulk superconductor)
  For x = 0: ψ = 0 (vortex core / domain wall center)
"""
        return psi, steps
    
    def compute_field_coherence(self, A2: float = None) -> Tuple[float, str]:
        """
        Compute |ψ|² from q-scope Channel 2 amplitude.
        
        Args:
            A2: Channel 2 amplitude (V)
            
        Returns:
            psi_squared: Field coherence intensity
            steps: Calculation explanation
        """
        if A2 is None:
            A2 = self.A2_reference
            
        # Map amplitude to coherence (normalized to reference)
        psi_squared = (A2 / self.A2_reference)**2 * self.psi_max**2
        
        steps = f"""Field Coherence from Q-Scope Data:
  
  |ψ|² = (A₂/A₂_ref)² × ψ_max²
  |ψ|² = ({A2}/{self.A2_reference})² × {self.psi_max**2}
  |ψ|² = {psi_squared:.6f}
  
  A₂ = 3.102 V (consistent across Groups #1-12)
  → Stable coherence indicates superconducting permanence
"""
        return psi_squared, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Ginzburg-Landau Field Model."""
        tests = []
        all_passed = True
        
        # Test 1: α coefficient at reference f_dT
        alpha, _ = self.compute_alpha(f_dT=40.0)
        t1 = 0.5 < alpha < 2.0  # Should be ~1.0
        tests.append(f"Test 1: α(f_dT=40Hz) = {alpha:.4f}, in [0.5, 2.0]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: α negative below T_c
        alpha_cold, _ = self.compute_alpha(T=4.2)
        t2 = alpha_cold < 0
        tests.append(f"Test 2: α(T=4.2K) = {alpha_cold:.4f} < 0: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: β decreases with |ψ|²
        beta_low, _ = self.compute_beta(0.1)
        beta_high, _ = self.compute_beta(0.9)
        t3 = beta_low > beta_high
        tests.append(f"Test 3: β(0.1)={beta_low:.4f} > β(0.9)={beta_high:.4f}: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Order parameter at reference amplitude
        psi_sq, _ = self.compute_field_coherence(3.102)
        t4 = 0.99 < psi_sq < 1.01
        tests.append(f"Test 4: |ψ|²(A₂=3.102V) = {psi_sq:.6f} ≈ 1: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"GinzburgLandauFieldModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class BogoliubovDeGennesModel:
    """
    Bogoliubov-de Gennes Model (U_b) - Quasiparticle Resonance
    
    Describes quasiparticle excitations in the superconductor, governing
    resonant interactions within the UQFF field.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    ┌                              ┐ ┌   ┐     ┌   ┐
    │ -ℏ²/(2m)∇² + V       Δ      │ │ u │     │ u │
    │                              │ │   │ = E │   │
    │      Δ*         ℏ²/(2m)∇² - V│ │ v │     │ v │
    └                              ┘ └   ┘     └   ┘
    
    Where:
        u, v : Quasiparticle wavefunctions (particle and hole components)
        ℏ : Reduced Planck constant (1.055 × 10⁻³⁴ J·s)
        m : Effective mass of electrons
        V : Potential energy
        Δ : Superconducting gap (related to order parameter ψ)
        E : Energy eigenvalue
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Δ (superconducting gap) determines minimum excitation energy
    - Quasiparticles are superpositions of electrons and holes
    - In UQFF: Δ ∝ f_dT, linking gap to temporal dynamics
    - The 1.2 THz hole influences Δ through low-energy signal reversal
    
    CONNECTION TO Q-SCOPE DATA:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Slowing f_dT (125 Hz → 40 Hz) suggests decreasing Δ
    - Stable A₂ = 3.102 V indicates constant E (low-energy resonant state)
    - Cooper pair binding energy ∝ Δ
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Physical constants
        self.hbar = 1.055e-34        # Reduced Planck constant (J·s)
        self.m_e = 9.109e-31         # Electron mass (kg)
        self.m_eff = 1.0             # Effective mass ratio (m*/m_e)
        
        # BCS parameters
        self.k_B = 1.381e-23         # Boltzmann constant (J/K)
        self.T_c = 9.2               # Critical temperature (K) - Nb
        self.Delta_0 = 1.5e-3 * 1.602e-19  # Gap at T=0 (J), ~1.5 meV
        
        # UQFF parameters
        self.k_Delta = 1e-24         # Δ-frequency coupling (J/Hz)
        self.f_THz_hole = 1.2e12     # 1.2 THz hole frequency
        
        # Q-scope reference
        self.f_dT_reference = 40.0   # Hz
        
    def compute_gap_temperature(self, T: float) -> Tuple[float, str]:
        """
        Compute superconducting gap Δ(T) using BCS approximation.
        
        Args:
            T: Temperature (K)
            
        Returns:
            Delta: Superconducting gap (J)
            steps: Calculation explanation
        """
        import math
        
        if T >= self.T_c:
            Delta = 0.0
            steps = f"T = {T} K ≥ T_c = {self.T_c} K → Δ = 0 (normal state)"
        else:
            # BCS approximation: Δ(T) ≈ Δ(0) × tanh(1.74 × √(T_c/T - 1))
            ratio = math.sqrt(self.T_c / T - 1)
            Delta = self.Delta_0 * math.tanh(1.74 * ratio)
            Delta_meV = Delta / 1.602e-22  # Convert to meV
            
            steps = f"""Superconducting Gap Δ(T) - BCS Approximation:
  
  Δ(T) = Δ(0) × tanh(1.74 × √(T_c/T - 1))
  
  Parameters:
    T = {T} K
    T_c = {self.T_c} K
    Δ(0) = {self.Delta_0 / 1.602e-22:.4f} meV
  
  Result:
    √(T_c/T - 1) = {ratio:.4f}
    Δ(T) = {Delta_meV:.4f} meV = {Delta:.4e} J
"""
        return Delta, steps
    
    def compute_gap_frequency(self, f_dT: float = None) -> Tuple[float, str]:
        """
        Compute Δ from UQFF temporal frequency.
        
        Args:
            f_dT: Temporal dynamics frequency (Hz)
            
        Returns:
            Delta: Superconducting gap (J)
            steps: Calculation explanation
        """
        if f_dT is None:
            f_dT = self.f_dT_reference
            
        Delta = self.k_Delta * f_dT
        Delta_meV = Delta / 1.602e-22
        
        steps = f"""Superconducting Gap Δ(f_dT) - UQFF Mode:
  
  Δ = k_Δ × f_dT
  Δ = {self.k_Delta:.4e} J/Hz × {f_dT} Hz
  Δ = {Delta:.4e} J = {Delta_meV:.4e} meV
  
  The slowing f_dT (125 Hz → 40 Hz) indicates:
  - Decreasing excitation energy
  - System approaching ground state
  - Enhanced superconducting coherence
"""
        return Delta, steps
    
    def compute_coherence_length(self, Delta: float) -> Tuple[float, str]:
        """
        Compute BCS coherence length ξ₀.
        
        Args:
            Delta: Superconducting gap (J)
            
        Returns:
            xi_0: Coherence length (m)
            steps: Calculation explanation
        """
        import math
        
        if Delta <= 0:
            xi_0 = float('inf')
            steps = "Δ = 0 → ξ₀ = ∞ (normal state)"
        else:
            # ξ₀ = ℏ v_F / (π Δ), using v_F ≈ 2×10⁶ m/s for metals
            v_F = 2e6  # Fermi velocity (m/s)
            xi_0 = self.hbar * v_F / (math.pi * Delta)
            
            steps = f"""BCS Coherence Length ξ₀:
  
  ξ₀ = ℏ v_F / (π Δ)
  
  Parameters:
    ℏ = {self.hbar:.4e} J·s
    v_F = {v_F:.4e} m/s (Fermi velocity)
    Δ = {Delta:.4e} J
  
  Result:
    ξ₀ = {xi_0:.4e} m = {xi_0 * 1e9:.2f} nm
  
  ξ₀ represents Cooper pair size / vortex core radius.
"""
        return xi_0, steps
    
    def compute_quasiparticle_energy(self, k: float, Delta: float) -> Tuple[float, str]:
        """
        Compute quasiparticle excitation energy E(k).
        
        Args:
            k: Wavevector deviation from Fermi surface (1/m)
            Delta: Superconducting gap (J)
            
        Returns:
            E: Quasiparticle energy (J)
            steps: Calculation explanation
        """
        import math
        
        # E_k = √(ε_k² + Δ²), where ε_k = ℏ²k²/(2m) - E_F ≈ ℏ v_F k
        v_F = 2e6  # Fermi velocity
        epsilon_k = self.hbar * v_F * abs(k)
        E = math.sqrt(epsilon_k**2 + Delta**2)
        
        E_meV = E / 1.602e-22
        
        steps = f"""Quasiparticle Energy E(k):
  
  E(k) = √(ε_k² + Δ²)
  
  Where ε_k = ℏ v_F k (deviation from Fermi energy)
  
  Parameters:
    k = {k:.4e} m⁻¹
    ε_k = {epsilon_k:.4e} J
    Δ = {Delta:.4e} J
  
  Result:
    E = {E:.4e} J = {E_meV:.4f} meV
  
  At k = 0 (Fermi surface): E = |Δ| (minimum excitation)
"""
        return E, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Bogoliubov-de Gennes Model."""
        tests = []
        all_passed = True
        
        # Test 1: Gap at T=0 > 0
        Delta_0, _ = self.compute_gap_temperature(0.1)
        t1 = Delta_0 > 0
        tests.append(f"Test 1: Δ(T=0.1K) = {Delta_0:.4e} J > 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Gap = 0 above T_c
        Delta_hot, _ = self.compute_gap_temperature(15.0)
        t2 = Delta_hot == 0
        tests.append(f"Test 2: Δ(T=15K) = {Delta_hot} = 0: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Coherence length physical (1-1000 nm)
        xi, _ = self.compute_coherence_length(self.Delta_0)
        xi_nm = xi * 1e9
        t3 = 1 < xi_nm < 1000
        tests.append(f"Test 3: ξ₀ = {xi_nm:.2f} nm in [1, 1000]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: E(k=0) = Δ (gap minimum)
        E_min, _ = self.compute_quasiparticle_energy(0, self.Delta_0)
        t4 = abs(E_min - self.Delta_0) / self.Delta_0 < 0.01
        tests.append(f"Test 4: E(k=0) = {E_min:.4e} ≈ Δ: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"BogoliubovDeGennesModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class QWaveResonanceModel:
    """
    Q-Wave Resonance Model (U_r) - Universal Resonance Equation
    
    The cornerstone of UQFF's gravity, defining all interactions as
    resonant q-wave dynamics, unifying forces through frequency and amplitude.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
    
    Where:
        A : Channel 1 amplitude (smooth q-wave) ≈ 0.4910 V
        A₂ : Channel 2 amplitude (eccentric) = 3.102 V (constant)
        f : Primary frequency (varies: 5.455 kHz → 976.68 Hz)
        φ : Phase shift between channels
        t : Time (s)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    Two-channel oscilloscope data reveals:
    - Channel 1 (smooth): Variable amplitude/frequency, sinusoidal
    - Channel 2 (eccentric): Stable amplitude, linked to flux pinning
    
    The combined signal U_r represents universal resonant interactions,
    replacing traditional gravitational forces with frequency-mediated dynamics.
    
    EMPIRICAL VALUES (Groups #1-12):
    ─────────────────────────────────────────────────────────────────────────────
    
    - A: 0.4604 V to 0.4963 V (V_p-p/2)
    - A₂: 3.102 V (constant across all groups)
    - f: 5.455 kHz (Group #1) → 976.68 Hz (Group #12)
    - dA = A₂ - A = 5.205 V (constant)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Q-scope empirical values
        self.A1_default = 0.4910     # Channel 1 amplitude (V)
        self.A2_default = 3.102      # Channel 2 amplitude (V) - constant
        self.dA_constant = 5.205     # Amplitude difference (V) - constant
        
        # Frequency ranges from Groups #1-12
        self.f_group1 = 5455.0       # Hz (Group #1)
        self.f_group12 = 976.68      # Hz (Group #12)
        
        # Phase (assumed negligible but measurable)
        self.phi_default = 0.0       # radians
        
    def compute_U_r(self, t: float, f: float = None, A1: float = None, 
                    A2: float = None, phi: float = None) -> Tuple[float, str]:
        """
        Compute universal resonance U_r at time t.
        
        Args:
            t: Time (s)
            f: Frequency (Hz)
            A1: Channel 1 amplitude (V)
            A2: Channel 2 amplitude (V)
            phi: Phase shift (radians)
            
        Returns:
            U_r: Resonance value (V)
            steps: Calculation explanation
        """
        import math
        
        if f is None:
            f = self.f_group12
        if A1 is None:
            A1 = self.A1_default
        if A2 is None:
            A2 = self.A2_default
        if phi is None:
            phi = self.phi_default
            
        omega = 2 * math.pi * f
        term1 = A1 * math.sin(omega * t)
        term2 = A2 * math.sin(omega * t + phi)
        U_r = term1 + term2
        
        steps = f"""Universal Resonance U_r(t):
  
  U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
  
  Parameters:
    A (Channel 1) = {A1:.4f} V
    A₂ (Channel 2) = {A2:.4f} V
    f = {f:.2f} Hz
    φ = {phi:.4f} rad
    t = {t:.6f} s
  
  Calculation:
    ω = 2πf = {omega:.2f} rad/s
    Term 1: A×sin(ωt) = {term1:.4f} V
    Term 2: A₂×sin(ωt+φ) = {term2:.4f} V
  
  Result:
    U_r = {U_r:.4f} V
"""
        return U_r, steps
    
    def compute_combined_amplitude(self, A1: float = None, A2: float = None, 
                                   phi: float = 0) -> Tuple[float, str]:
        """
        Compute combined amplitude of two-channel signal.
        
        Args:
            A1: Channel 1 amplitude (V)
            A2: Channel 2 amplitude (V)
            phi: Phase difference (radians)
            
        Returns:
            A_combined: Combined amplitude (V)
            steps: Calculation explanation
        """
        import math
        
        if A1 is None:
            A1 = self.A1_default
        if A2 is None:
            A2 = self.A2_default
            
        # A_combined = √(A1² + A2² + 2×A1×A2×cos(φ))
        A_combined = math.sqrt(A1**2 + A2**2 + 2*A1*A2*math.cos(phi))
        
        steps = f"""Combined Amplitude:
  
  A_combined = √(A₁² + A₂² + 2×A₁×A₂×cos(φ))
  
  Parameters:
    A₁ = {A1:.4f} V
    A₂ = {A2:.4f} V
    φ = {phi:.4f} rad
    cos(φ) = {math.cos(phi):.4f}
  
  Result:
    A_combined = √({A1**2:.4f} + {A2**2:.4f} + {2*A1*A2*math.cos(phi):.4f})
    A_combined = {A_combined:.4f} V
  
  For φ = 0 (in-phase): A_combined = A₁ + A₂ = {A1 + A2:.4f} V
  For φ = π (anti-phase): A_combined = |A₂ - A₁| = {abs(A2 - A1):.4f} V
"""
        return A_combined, steps
    
    def compute_frequency_ratio(self, f: float) -> Tuple[float, str]:
        """
        Compute frequency ratio relative to Group #1 reference.
        
        Args:
            f: Current frequency (Hz)
            
        Returns:
            ratio: f/f_group1
            steps: Calculation explanation
        """
        ratio = f / self.f_group1
        
        steps = f"""Frequency Ratio (System Evolution):
  
  Ratio = f / f_Group1
  Ratio = {f:.2f} / {self.f_group1:.2f}
  Ratio = {ratio:.4f}
  
  Group #1: f = 5.455 kHz (high energy/turbulent state)
  Group #12: f = 976.68 Hz (low energy/stable state)
  
  Ratio evolution: 1.0 → 0.179 indicates system stabilization
  through superconducting permanence.
"""
        return ratio, steps
    
    def get_group_data(self, group: int) -> Dict[str, float]:
        """Get empirical data for a specific q-scope group."""
        # Interpolated/representative values
        group_data = {
            1: {'f': 5455.0, 'A1': 0.4963, 'dT_ms': 8.0, 'f_dT': 125.0},
            6: {'f': 3500.0, 'A1': 0.4850, 'dT_ms': 12.0, 'f_dT': 83.33},
            10: {'f': 1500.0, 'A1': 0.4700, 'dT_ms': 18.0, 'f_dT': 55.56},
            11: {'f': 1000.0, 'A1': 0.4650, 'dT_ms': 20.0, 'f_dT': 50.0},
            12: {'f': 976.68, 'A1': 0.4604, 'dT_ms': 25.0, 'f_dT': 40.0},
        }
        if group in group_data:
            return group_data[group]
        else:
            # Linear interpolation
            return {'f': self.f_group1 * (1 - 0.08 * group), 
                    'A1': self.A1_default, 'dT_ms': 8 + 1.5*group, 
                    'f_dT': 125 - 7*group}
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Q-Wave Resonance Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: U_r at t=0 gives initial phase state
        U_r_0, _ = self.compute_U_r(0, phi=0)
        t1 = abs(U_r_0) < 0.01  # sin(0) = 0
        tests.append(f"Test 1: U_r(t=0, φ=0) = {U_r_0:.4f} ≈ 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Combined amplitude for in-phase
        A_comb, _ = self.compute_combined_amplitude(phi=0)
        expected = self.A1_default + self.A2_default
        t2 = abs(A_comb - expected) < 0.01
        tests.append(f"Test 2: A_combined(φ=0) = {A_comb:.4f} ≈ {expected:.4f}: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Frequency ratio Group #12
        ratio, _ = self.compute_frequency_ratio(self.f_group12)
        t3 = 0.15 < ratio < 0.20
        tests.append(f"Test 3: f_ratio(Group12) = {ratio:.4f} ∈ [0.15, 0.20]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: dA constant check
        dA = self.A2_default - self.A1_default
        t4 = abs(dA - 2.611) < 0.1  # Actual dA from A2 - A1
        tests.append(f"Test 4: dA = A₂ - A₁ = {dA:.4f} ≈ 2.611: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"QWaveResonanceModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class TemporalDynamicsModel:
    """
    Temporal Dynamics Model (U_t) - Resonant Time Framework
    
    Governs the temporal evolution of the UQFF system, replacing spacetime
    with resonant timing intervals derived from q-scope dT measurements.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    U_t = 1/dT
    f_dT = 1/dT
    
    Where:
        dT : Temporal resonance interval (s)
        f_dT : Frequency from time difference (Hz)
        U_t : Temporal dynamics parameter
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    The slowing dT (8 ms → 25 ms) across Groups #1-12 indicates:
    - Transition from turbulent to laminar vortex dynamics
    - System stabilization through cooling or magnetic effects
    - Approach to superconducting permanence
    
    EMPIRICAL VALUES:
    ─────────────────────────────────────────────────────────────────────────────
    
    Group #1:  dT = 8 ms,  f_dT = 125.00 Hz
    Group #10: dT = 10-12 ms, f_dT = 83-100 Hz  
    Group #11: dT = 15-20 ms, f_dT = 50-67 Hz
    Group #12: dT = 25 ms, f_dT = 40.00 Hz
    
    TIMING REFERENCE:
    - Images spaced 534 ms apart
    - Image 1: 0.000 s → Image 73: 38.448 s
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Q-scope timing data
        self.image_interval = 0.534    # Seconds between images
        self.total_images = 73         # Images 1-73
        self.total_time = 38.448       # Total observation time (s)
        
        # dT values from groups
        self.dT_group1 = 0.008         # 8 ms
        self.dT_group12 = 0.025        # 25 ms
        
        # Derived frequencies
        self.f_dT_group1 = 125.0       # Hz
        self.f_dT_group12 = 40.0       # Hz
        
    def compute_U_t(self, dT: float) -> Tuple[float, str]:
        """
        Compute temporal dynamics U_t from dT.
        
        Args:
            dT: Time difference (s)
            
        Returns:
            U_t: Temporal dynamics parameter (Hz)
            steps: Calculation explanation
        """
        if dT <= 0:
            raise ValueError("dT must be positive")
            
        U_t = 1.0 / dT
        
        steps = f"""Temporal Dynamics U_t:
  
  U_t = 1/dT = f_dT
  
  Parameters:
    dT = {dT:.6f} s = {dT*1000:.2f} ms
  
  Result:
    U_t = {U_t:.4f} Hz
  
  Interpretation:
    Higher U_t → rapidly changing system (turbulent)
    Lower U_t → slowly changing system (laminar/stable)
"""
        return U_t, steps
    
    def compute_dT_evolution(self, group: int) -> Tuple[float, float, str]:
        """
        Compute dT and f_dT for a given group number.
        
        Args:
            group: Q-scope group number (1-12)
            
        Returns:
            dT: Time difference (s)
            f_dT: dT frequency (Hz)
            steps: Calculation explanation
        """
        # Linear interpolation between Group 1 and Group 12
        if group < 1:
            group = 1
        elif group > 12:
            group = 12
            
        # dT increases linearly from 8 ms to 25 ms
        dT = self.dT_group1 + (self.dT_group12 - self.dT_group1) * (group - 1) / 11
        f_dT = 1.0 / dT
        
        steps = f"""dT Evolution for Group #{group}:
  
  Linear interpolation:
    dT(group) = dT_1 + (dT_12 - dT_1) × (group - 1) / 11
    dT = {self.dT_group1*1000:.1f} + ({self.dT_group12*1000:.1f} - {self.dT_group1*1000:.1f}) × ({group} - 1) / 11
    dT = {dT*1000:.2f} ms
  
  Result:
    dT = {dT:.6f} s
    f_dT = 1/dT = {f_dT:.2f} Hz
  
  Trend: f_dT decreases from 125 Hz (Group 1) to 40 Hz (Group 12)
  → System stabilization over time
"""
        return dT, f_dT, steps
    
    def compute_stabilization_rate(self) -> Tuple[float, str]:
        """
        Compute rate of frequency stabilization across observation.
        
        Returns:
            rate: df_dT/dt (Hz/s)
            steps: Calculation explanation
        """
        # f_dT drops from 125 Hz to 40 Hz over ~38.5 s
        delta_f = self.f_dT_group1 - self.f_dT_group12
        delta_t = self.total_time
        rate = delta_f / delta_t
        
        steps = f"""Stabilization Rate:
  
  Rate = Δf_dT / Δt
  
  Parameters:
    f_dT(Group 1) = {self.f_dT_group1} Hz
    f_dT(Group 12) = {self.f_dT_group12} Hz
    Δf_dT = {delta_f:.2f} Hz
    Δt = {delta_t:.3f} s
  
  Result:
    Rate = {rate:.4f} Hz/s
    
  The system loses {delta_f:.0f} Hz of temporal fluctuation
  over {delta_t:.1f} seconds, indicating progressive stabilization.
"""
        return rate, steps
    
    def compute_image_timestamp(self, image_number: int) -> Tuple[float, str]:
        """
        Compute timestamp for a given image number.
        
        Args:
            image_number: Image number (1-73)
            
        Returns:
            timestamp: Time since start (s)
            steps: Calculation explanation
        """
        if image_number < 1 or image_number > self.total_images:
            raise ValueError(f"Image number must be between 1 and {self.total_images}")
            
        timestamp = (image_number - 1) * self.image_interval
        
        steps = f"""Image Timestamp:
  
  t = (image_number - 1) × interval
  t = ({image_number} - 1) × {self.image_interval} s
  t = {timestamp:.3f} s
  
  Image {image_number} captured at t = {timestamp:.3f} s
"""
        return timestamp, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Temporal Dynamics Model."""
        tests = []
        all_passed = True
        
        # Test 1: U_t for Group 12 dT
        U_t, _ = self.compute_U_t(0.025)
        t1 = abs(U_t - 40.0) < 0.1
        tests.append(f"Test 1: U_t(dT=25ms) = {U_t:.2f} Hz ≈ 40: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: dT evolution spans correct range
        dT_1, f_1, _ = self.compute_dT_evolution(1)
        dT_12, f_12, _ = self.compute_dT_evolution(12)
        t2 = abs(f_1 - 125.0) < 1.0 and abs(f_12 - 40.0) < 1.0
        tests.append(f"Test 2: f_dT ranges {f_1:.0f} → {f_12:.0f} Hz: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Total timestamp matches
        t_73, _ = self.compute_image_timestamp(73)
        t3 = abs(t_73 - 38.448) < 0.1
        tests.append(f"Test 3: t(image 73) = {t_73:.3f} s ≈ 38.448: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Stabilization rate physical
        rate, _ = self.compute_stabilization_rate()
        t4 = 2.0 < rate < 3.0
        tests.append(f"Test 4: Stabilization rate = {rate:.3f} Hz/s ∈ [2, 3]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"TemporalDynamicsModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class AmplitudeStabilityModel:
    """
    Amplitude Stability Model (U_A) - Resonant Energy Conservation
    
    Captures the stability of amplitudes across q-scope channels, ensuring
    energy coherence within the UQFF superconducting framework.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    U_A = A₂ - A = dA
    
    Where:
        A : Channel 1 amplitude ≈ 0.4910 V (variable)
        A₂ : Channel 2 amplitude = 3.102 V (constant)
        dA : Amplitude difference = 5.205 V (empirically constant)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    The constant dA = 5.205 V across all groups indicates:
    - Universal energy stability (superconducting permanence)
    - Flux pinning maintains field coherence
    - Resonant energy conservation
    
    Note: The actual A₂ - A = 3.102 - 0.491 = 2.611 V
    The 5.205 V constant may include a calibration factor or represent
    peak-to-peak measurements (V_p-p = 2 × A).
    
    ENERGY INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    If we interpret V_p-p values:
    - V_p-p,1 ~ 1.0 V (920.7 mV - 992.1 mV)
    - V_p-p,2 ~ 6.2 V (2 × 3.102 V)
    - dV_p-p = 6.2 - 1.0 = 5.2 V ≈ 5.205 V ✓
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Empirical amplitude values
        self.A1_reference = 0.4910      # Channel 1 amplitude (V)
        self.A2_constant = 3.102        # Channel 2 amplitude (V)
        self.dA_empirical = 5.205       # Empirical constant (V)
        
        # Voltage ranges from q-scope data
        self.Vpp_range = (0.9207, 0.9921)  # V_p-p range for Channel 1
        self.Veff_range = (0.2949, 0.2979) # V_eff range
        
    def compute_U_A(self, A1: float = None, A2: float = None) -> Tuple[float, str]:
        """
        Compute amplitude stability U_A.
        
        Args:
            A1: Channel 1 amplitude (V)
            A2: Channel 2 amplitude (V)
            
        Returns:
            U_A: Amplitude difference (V)
            steps: Calculation explanation
        """
        if A1 is None:
            A1 = self.A1_reference
        if A2 is None:
            A2 = self.A2_constant
            
        U_A = A2 - A1
        
        steps = f"""Amplitude Stability U_A:
  
  U_A = A₂ - A
  U_A = {A2:.4f} - {A1:.4f}
  U_A = {U_A:.4f} V
  
  Empirical constant from q-scope: dA = 5.205 V
  Actual computed difference: {U_A:.4f} V
  
  The difference suggests V_p-p interpretation:
    dV_p-p = 2×A₂ - V_p-p,1
    dV_p-p = {2*A2:.2f} - {2*A1:.2f} ≈ 5.2 V
"""
        return U_A, steps
    
    def compute_stability_deviation(self, A2_measured: float) -> Tuple[float, str]:
        """
        Compute deviation from stable A₂ reference.
        
        Args:
            A2_measured: Measured Channel 2 amplitude (V)
            
        Returns:
            deviation: Fractional deviation from reference
            steps: Calculation explanation
        """
        deviation = (A2_measured - self.A2_constant) / self.A2_constant
        
        steps = f"""Stability Deviation:
  
  δ = (A₂_measured - A₂_ref) / A₂_ref
  δ = ({A2_measured:.4f} - {self.A2_constant:.4f}) / {self.A2_constant:.4f}
  δ = {deviation:.6f} = {deviation*100:.4f}%
  
  Interpretation:
    δ ≈ 0: Stable superconducting state
    |δ| > 0.01: Potential perturbation or phase transition
"""
        return deviation, steps
    
    def compute_energy_ratio(self, A1: float = None, A2: float = None) -> Tuple[float, str]:
        """
        Compute energy ratio between channels (∝ A²).
        
        Args:
            A1: Channel 1 amplitude (V)
            A2: Channel 2 amplitude (V)
            
        Returns:
            ratio: E₂/E₁ = (A₂/A₁)²
            steps: Calculation explanation
        """
        if A1 is None:
            A1 = self.A1_reference
        if A2 is None:
            A2 = self.A2_constant
            
        ratio = (A2 / A1) ** 2
        
        steps = f"""Energy Ratio (E ∝ A²):
  
  E₂/E₁ = (A₂/A₁)²
  E₂/E₁ = ({A2:.4f}/{A1:.4f})²
  E₂/E₁ = {A2/A1:.4f}²
  E₂/E₁ = {ratio:.2f}
  
  Channel 2 carries {ratio:.1f}× more energy than Channel 1.
  This energy differential drives resonant flux pinning.
"""
        return ratio, steps
    
    def compute_Vpp_to_amplitude(self, Vpp: float) -> Tuple[float, str]:
        """
        Convert peak-to-peak voltage to amplitude.
        
        Args:
            Vpp: Peak-to-peak voltage (V)
            
        Returns:
            A: Amplitude (V)
            steps: Calculation explanation
        """
        A = Vpp / 2
        
        steps = f"""V_p-p to Amplitude Conversion:
  
  A = V_p-p / 2
  A = {Vpp:.4f} / 2
  A = {A:.4f} V
  
  For sinusoidal signal: V_p-p = 2 × A
"""
        return A, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Amplitude Stability Model."""
        tests = []
        all_passed = True
        
        # Test 1: U_A at reference values
        U_A, _ = self.compute_U_A()
        t1 = 2.5 < U_A < 2.7
        tests.append(f"Test 1: U_A = A₂ - A = {U_A:.4f} V ∈ [2.5, 2.7]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Stability deviation at constant A₂
        dev, _ = self.compute_stability_deviation(3.102)
        t2 = abs(dev) < 0.001
        tests.append(f"Test 2: δ(A₂=3.102) = {dev:.6f} ≈ 0: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Energy ratio physical
        ratio, _ = self.compute_energy_ratio()
        t3 = 30 < ratio < 50
        tests.append(f"Test 3: E₂/E₁ = {ratio:.2f} ∈ [30, 50]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: V_p-p to amplitude conversion
        A, _ = self.compute_Vpp_to_amplitude(0.9500)
        t4 = abs(A - 0.475) < 0.001
        tests.append(f"Test 4: A(V_pp=0.95) = {A:.4f} ≈ 0.475: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"AmplitudeStabilityModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class SuperconductingCoherenceModel:
    """
    Superconducting Coherence Model (SC_m) - Universal Coherence Metric
    
    Quantifies the coherence of the superconducting state, replacing
    mass-energy equivalence with field coherence in the UQFF framework.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    SC_m = |ψ|² / ∫|ψ|² dV
    
    Where:
        ψ : Order parameter from Ginzburg-Landau equation (U_g)
        |ψ|² : Local field intensity
        ∫|ψ|² dV : Total field intensity over volume V
        SC_m : Normalized coherence metric [0, 1]
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    SC_m measures local coherence of the superconductive field:
    - SC_m → 1: Perfect coherence at a point (delta function)
    - SC_m → 0: Distributed/decoherent state
    - SC_m ≈ 0.99: Stable superconducting permanence
    
    CONNECTION TO Q-SCOPE DATA:
    ─────────────────────────────────────────────────────────────────────────────
    
    The stable A₂ = 3.102 V implies high SC_m ≈ 1, indicating:
    - Strong flux pinning at resonant nodes
    - Universal field coherence maintained
    - Energy stability through superconducting permanence
    
    CALIBRATED VALUE (H_SCm):
    - H_SCm ≈ 0.99 for stable orbital configurations
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Reference coherence values
        self.H_SCm = 0.99            # Calibrated SC_m for stable orbits
        self.SC_m_perfect = 1.0      # Ideal coherence
        
        # A₂ reference for empirical SC_m estimation
        self.A2_reference = 3.102    # V
        
        # Coherence length scale
        self.xi_0 = 1e-6             # Coherence length (m) - typical superconductor
        
    def compute_SC_m_local(self, psi_squared: float, psi_squared_total: float) -> Tuple[float, str]:
        """
        Compute local coherence metric SC_m.
        
        Args:
            psi_squared: Local |ψ|² value
            psi_squared_total: ∫|ψ|² dV over system
            
        Returns:
            SC_m: Coherence metric [0, 1]
            steps: Calculation explanation
        """
        if psi_squared_total <= 0:
            raise ValueError("Total |ψ|² must be positive")
            
        SC_m = psi_squared / psi_squared_total
        
        steps = f"""Superconducting Coherence Metric SC_m:
  
  SC_m = |ψ|² / ∫|ψ|² dV
  
  Parameters:
    |ψ|² (local) = {psi_squared:.6f}
    ∫|ψ|² dV (total) = {psi_squared_total:.6f}
  
  Result:
    SC_m = {SC_m:.6f}
  
  Interpretation:
    SC_m = {SC_m:.4f} indicates {'high' if SC_m > 0.9 else 'moderate' if SC_m > 0.5 else 'low'} coherence.
"""
        return SC_m, steps
    
    def compute_SC_m_from_amplitude(self, A2: float = None) -> Tuple[float, str]:
        """
        Estimate SC_m from q-scope Channel 2 amplitude.
        
        Args:
            A2: Channel 2 amplitude (V)
            
        Returns:
            SC_m: Estimated coherence metric
            steps: Calculation explanation
        """
        if A2 is None:
            A2 = self.A2_reference
            
        # SC_m scales with A₂ relative to reference
        SC_m = min(1.0, (A2 / self.A2_reference) ** 2 * self.H_SCm)
        
        steps = f"""SC_m from Q-Scope Amplitude:
  
  SC_m = min(1, (A₂/A₂_ref)² × H_SCm)
  SC_m = min(1, ({A2:.4f}/{self.A2_reference:.4f})² × {self.H_SCm})
  SC_m = {SC_m:.6f}
  
  A₂ = 3.102 V (constant) → SC_m ≈ H_SCm = 0.99
  This represents stable superconducting coherence.
"""
        return SC_m, steps
    
    def compute_coherence_volume(self, SC_m: float, V_total: float) -> Tuple[float, str]:
        """
        Compute effective coherent volume.
        
        Args:
            SC_m: Coherence metric
            V_total: Total system volume (m³)
            
        Returns:
            V_coherent: Coherent volume (m³)
            steps: Calculation explanation
        """
        V_coherent = SC_m * V_total
        
        steps = f"""Coherent Volume:
  
  V_coherent = SC_m × V_total
  V_coherent = {SC_m:.4f} × {V_total:.4e} m³
  V_coherent = {V_coherent:.4e} m³
  
  For SC_m → 1: Entire system is coherent
  For SC_m → 0: Coherence localized to small region
"""
        return V_coherent, steps
    
    def compute_orbital_SC_m(self, theta: float, f_TRZ: float) -> Tuple[float, str]:
        """
        Compute SC_m for orbital configurations.
        
        SC_m = [SCm] × cos(θ) × f_TRZ
        
        Args:
            theta: Orbital inclination angle (radians)
            f_TRZ: Time Reversal Zone factor
            
        Returns:
            SC_m: Orbital coherence metric
            steps: Calculation explanation
        """
        import math
        
        SC_m = self.H_SCm * math.cos(theta) * f_TRZ
        
        steps = f"""Orbital SC_m:
  
  SC_m = [SCm] × cos(θ) × f_TRZ
  SC_m = {self.H_SCm} × cos({theta:.4f}) × {f_TRZ:.4f}
  SC_m = {self.H_SCm} × {math.cos(theta):.4f} × {f_TRZ:.4f}
  SC_m = {SC_m:.6f}
  
  Orbital coherence depends on:
  - Base [SCm] from flux pinning
  - Geometric factor cos(θ)
  - Time Reversal Zone modulation f_TRZ
"""
        return SC_m, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Superconducting Coherence Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: SC_m at reference amplitude
        SC_m, _ = self.compute_SC_m_from_amplitude(3.102)
        t1 = 0.98 < SC_m < 1.0
        tests.append(f"Test 1: SC_m(A₂=3.102V) = {SC_m:.4f} ∈ [0.98, 1.0]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: SC_m local normalization
        SC_m_local, _ = self.compute_SC_m_local(0.5, 1.0)
        t2 = abs(SC_m_local - 0.5) < 0.001
        tests.append(f"Test 2: SC_m(local) = {SC_m_local:.4f} = 0.5: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Coherent volume fraction
        V_coh, _ = self.compute_coherence_volume(0.99, 1.0)
        t3 = abs(V_coh - 0.99) < 0.01
        tests.append(f"Test 3: V_coherent = {V_coh:.4f} ≈ 0.99: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Orbital SC_m at θ=0, f_TRZ=1
        SC_m_orb, _ = self.compute_orbital_SC_m(0, 1.0)
        t4 = abs(SC_m_orb - self.H_SCm) < 0.001
        tests.append(f"Test 4: SC_m(orbital, θ=0) = {SC_m_orb:.4f} ≈ H_SCm: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"SuperconductingCoherenceModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


