# SMBH DYNAMICS MODELS (5 Models)
# Supermassive Black Hole Physics and AGN Dynamics
# ═══════════════════════════════════════════════════════════════════════════════

class BHMFEvolutionModel:
    """
    Black Hole Mass Function Evolution Model
    
    Models the evolution of the SMBH mass distribution over cosmic time,
    tracking population growth through accretion and mergers.
    
    KEY EQUATION (Continuity):
    ─────────────────────────────────────────────────────────────────────────────
    
    ∂Φ(M,z)/∂z + ∂[Φ(M,z)⟨Ṁ⟩]/∂M = S(M,z)
    
    Where:
        Φ(M,z) : Number density of SMBHs with mass M at redshift z (Mpc⁻³ dex⁻¹)
        ⟨Ṁ⟩ : Average accretion rate (M_☉/yr)
        S(M,z) : Source/sink term (mergers, seeding)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Left side: Conservation of SMBH number density
    - ∂Φ/∂z: Change with cosmic time
    - ∂(Φ⟨Ṁ⟩)/∂M: Growth through accretion
    - S(M,z): Mergers add pairs, seeding creates new SMBHs
    
    KEY RESULTS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Large fraction of SMBHs in place by z ≈ 4 for ε ≥ 0.07
    - Implies massive seeds (M ~ 10⁵ M_☉) required
    - Local BHMF: Φ(M) ∝ M^(-1.2) for M > 10⁷ M_☉
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.M_sun = 1.989e30      # Solar mass (kg)
        self.Mpc_to_m = 3.086e22   # Mpc to meters
        
        # Local BHMF parameters (Schechter-like function)
        self.Phi_star = 1e-3       # Normalization (Mpc⁻³ dex⁻¹)
        self.M_star = 1e8          # Characteristic mass (M_☉)
        self.alpha = -1.2          # Low-mass slope
        
        # Accretion parameters
        self.epsilon_rad = 0.1     # Radiative efficiency
        self.t_Salp = 4.5e7        # Salpeter time (yr)
        
    def compute_local_BHMF(self, M: float) -> Tuple[float, str]:
        """
        Compute local (z=0) black hole mass function.
        
        Args:
            M: Black hole mass (M_☉)
            
        Returns:
            Phi: Number density (Mpc⁻³ dex⁻¹)
            steps: Calculation explanation
        """
        import math
        
        # Schechter function: Φ(M) = Φ* × (M/M*)^α × exp(-M/M*)
        x = M / self.M_star
        Phi = self.Phi_star * (x ** self.alpha) * math.exp(-x)
        
        steps = f"""Local Black Hole Mass Function:
  
  Φ(M) = Φ* × (M/M*)^α × exp(-M/M*)
  
  Parameters:
    M = {M:.4e} M_☉
    Φ* = {self.Phi_star:.4e} Mpc⁻³ dex⁻¹
    M* = {self.M_star:.4e} M_☉
    α = {self.alpha}
  
  Calculation:
    M/M* = {x:.4f}
    (M/M*)^α = {x**self.alpha:.4e}
    exp(-M/M*) = {math.exp(-x):.4e}
  
  Result:
    Φ(M) = {Phi:.4e} Mpc⁻³ dex⁻¹
    
  This means {Phi * 1e9:.2f} SMBHs per Gpc³ in this mass bin.
"""
        return Phi, steps
    
    def compute_mass_density(self, M_min: float = 1e6, M_max: float = 1e10, 
                              n_bins: int = 100) -> Tuple[float, str]:
        """
        Compute total SMBH mass density from BHMF.
        
        Args:
            M_min: Minimum mass (M_☉)
            M_max: Maximum mass (M_☉)
            n_bins: Integration bins
            
        Returns:
            rho_BH: Mass density (M_☉ Mpc⁻³)
            steps: Calculation explanation
        """
        import math
        
        # ρ_BH = ∫ M × Φ(M) × d(log M)
        log_M_min = math.log10(M_min)
        log_M_max = math.log10(M_max)
        d_log_M = (log_M_max - log_M_min) / n_bins
        
        rho_BH = 0
        for i in range(n_bins):
            log_M = log_M_min + (i + 0.5) * d_log_M
            M = 10**log_M
            Phi, _ = self.compute_local_BHMF(M)
            rho_BH += M * Phi * d_log_M
        
        steps = f"""SMBH Mass Density:
  
  ρ_BH = ∫ M × Φ(M) d(log M)
  
  Integration range:
    M_min = {M_min:.4e} M_☉
    M_max = {M_max:.4e} M_☉
  
  Result:
    ρ_BH = {rho_BH:.4e} M_☉ Mpc⁻³
    ρ_BH = {rho_BH * self.M_sun / self.Mpc_to_m**3:.4e} kg m⁻³
    
  This represents the total SMBH contribution to cosmic mass density.
"""
        return rho_BH, steps
    
    def compute_e_folding_time(self, epsilon: float = None) -> Tuple[float, str]:
        """
        Compute e-folding (Salpeter) time for SMBH growth.
        
        t_Salp = ε × σ_T × c / (4π × G × m_p) ≈ 4.5 × 10⁷ yr × (ε/0.1)
        
        Args:
            epsilon: Radiative efficiency [0.05, 0.4]
            
        Returns:
            t_Salp: Salpeter time (yr)
            steps: Calculation explanation
        """
        if epsilon is None:
            epsilon = self.epsilon_rad
            
        t_Salp = 4.5e7 * (epsilon / 0.1)
        
        steps = f"""Salpeter (e-folding) Time:
  
  t_Salp ≈ 4.5 × 10⁷ yr × (ε/0.1)
  
  Parameters:
    ε (radiative efficiency) = {epsilon}
  
  Result:
    t_Salp = {t_Salp:.4e} yr
    
  At Eddington accretion, SMBH mass doubles every ~t_Salp.
  From 10² M_☉ to 10⁹ M_☉ requires ~23 e-foldings = {23*t_Salp/1e9:.2f} Gyr
"""
        return t_Salp, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate BHMF Evolution Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: BHMF peaks near M*
        Phi_low, _ = self.compute_local_BHMF(1e6)
        Phi_high, _ = self.compute_local_BHMF(1e10)
        t1 = Phi_low > Phi_high  # More low-mass SMBHs
        tests.append(f"Test 1: Φ(10⁶) = {Phi_low:.2e} > Φ(10¹⁰) = {Phi_high:.2e}: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Mass density in reasonable range (10⁴ - 10⁶ M_☉/Mpc³)
        rho, _ = self.compute_mass_density()
        t2 = 1e4 < rho < 1e6
        tests.append(f"Test 2: ρ_BH = {rho:.2e} M_☉/Mpc³ ∈ [10⁴, 10⁶]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Salpeter time ~45 Myr for ε=0.1
        t_Salp, _ = self.compute_e_folding_time(0.1)
        t3 = 4e7 < t_Salp < 5e7
        tests.append(f"Test 3: t_Salp(ε=0.1) = {t_Salp:.2e} yr ≈ 4.5×10⁷: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Higher efficiency → slower growth
        t_low, _ = self.compute_e_folding_time(0.05)
        t_high, _ = self.compute_e_folding_time(0.2)
        t4 = t_high > t_low
        tests.append(f"Test 4: t_Salp(ε=0.2) > t_Salp(ε=0.05): {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"BHMFEvolutionModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class BondiAccretionModel:
    """
    Bondi-Hoyle-Lyttleton Accretion Model
    
    Models spherical accretion of ambient gas onto a massive object,
    fundamental for SMBH feeding in galaxy centers.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    Ṁ = 4π × ρ_∞ × (GM/v_∞²)² × v_∞
    
    Simplified form:
    Ṁ = 4π × λ × ρ_∞ × (GM)² / c_s³
    
    Where:
        Ṁ : Accretion rate (kg/s or M_☉/yr)
        ρ_∞ : Ambient gas density (kg/m³)
        v_∞ : Relative velocity of gas (m/s)
        c_s : Sound speed (m/s)
        λ : Dimensionless factor (~0.25-1)
        G, M : Gravitational constant, BH mass
    
    PHYSICAL SCALES:
    ─────────────────────────────────────────────────────────────────────────────
    
    Bondi radius: r_B = GM/c_s² (where BH gravity dominates)
    
    For M = 10⁸ M_☉, T = 10⁷ K (hot halo):
    - r_B ~ 100 pc
    - Ṁ_Bondi ~ 0.01-1 M_☉/yr
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.M_sun = 1.989e30      # Solar mass (kg)
        self.k_B = 1.381e-23       # Boltzmann constant
        self.m_p = 1.673e-27       # Proton mass (kg)
        self.yr_s = 3.156e7        # Seconds per year
        
    def compute_sound_speed(self, T: float, mu: float = 0.6) -> Tuple[float, str]:
        """
        Compute sound speed in hot gas.
        
        c_s = √(γ k_B T / (μ m_p))
        
        Args:
            T: Temperature (K)
            mu: Mean molecular weight (0.6 for ionized H/He)
            
        Returns:
            c_s: Sound speed (m/s)
            steps: Calculation explanation
        """
        import math
        
        gamma = 5/3  # Monatomic ideal gas
        c_s = math.sqrt(gamma * self.k_B * T / (mu * self.m_p))
        
        steps = f"""Sound Speed:
  
  c_s = √(γ k_B T / (μ m_p))
  
  Parameters:
    T = {T:.4e} K
    γ = {gamma}
    μ = {mu}
  
  Result:
    c_s = √({gamma} × {self.k_B:.4e} × {T:.4e} / ({mu} × {self.m_p:.4e}))
    c_s = {c_s:.4e} m/s = {c_s/1e3:.1f} km/s
"""
        return c_s, steps
    
    def compute_bondi_radius(self, M: float, c_s: float) -> Tuple[float, str]:
        """
        Compute Bondi radius.
        
        Args:
            M: Black hole mass (kg)
            c_s: Sound speed (m/s)
            
        Returns:
            r_B: Bondi radius (m)
            steps: Calculation explanation
        """
        r_B = self.G * M / c_s**2
        pc = 3.086e16  # parsec in meters
        
        steps = f"""Bondi Radius:
  
  r_B = GM / c_s²
  r_B = {self.G:.4e} × {M:.4e} / {c_s:.4e}²
  r_B = {r_B:.4e} m = {r_B/pc:.2f} pc
  
  Inside r_B, BH gravity dominates over thermal pressure.
"""
        return r_B, steps
    
    def compute_accretion_rate(self, M: float, rho_inf: float, 
                               c_s: float = None, v_inf: float = None,
                               T: float = None) -> Tuple[float, str]:
        """
        Compute Bondi accretion rate.
        
        Args:
            M: Black hole mass (kg)
            rho_inf: Ambient density (kg/m³)
            c_s: Sound speed (m/s), optional
            v_inf: Relative velocity (m/s), optional
            T: Temperature (K), to compute c_s if not given
            
        Returns:
            M_dot: Accretion rate (M_☉/yr)
            steps: Calculation explanation
        """
        import math
        
        if c_s is None:
            if T is not None:
                c_s, _ = self.compute_sound_speed(T)
            else:
                c_s = 300e3  # Default 300 km/s for hot gas
        
        if v_inf is None:
            v_inf = c_s  # Subsonic limit
        
        # Ṁ = 4π × ρ_∞ × (GM)² / (c_s² + v_∞²)^(3/2)
        v_eff = math.sqrt(c_s**2 + v_inf**2)
        M_dot_SI = 4 * math.pi * rho_inf * (self.G * M)**2 / v_eff**3
        
        # Convert to M_☉/yr
        M_dot = M_dot_SI * self.yr_s / self.M_sun
        
        # Compare to Eddington rate
        M_dot_Edd = 4 * math.pi * self.G * M * self.m_p / (0.1 * 6.652e-29 * 2.998e8)
        M_dot_Edd_yr = M_dot_Edd * self.yr_s / self.M_sun
        
        steps = f"""Bondi Accretion Rate:
  
  Ṁ = 4π × ρ_∞ × (GM)² / v_eff³
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2e} M_☉
    ρ_∞ = {rho_inf:.4e} kg/m³
    c_s = {c_s:.4e} m/s = {c_s/1e3:.1f} km/s
    v_∞ = {v_inf:.4e} m/s
    v_eff = √(c_s² + v_∞²) = {v_eff:.4e} m/s
  
  Result:
    Ṁ = {M_dot_SI:.4e} kg/s = {M_dot:.4e} M_☉/yr
  
  Eddington rate: Ṁ_Edd ≈ {M_dot_Edd_yr:.4e} M_☉/yr
  Ṁ/Ṁ_Edd ≈ {M_dot/M_dot_Edd_yr:.4f}
"""
        return M_dot, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Bondi Accretion Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Sound speed at 10⁷ K ~ 500 km/s
        c_s, _ = self.compute_sound_speed(1e7)
        t1 = 400e3 < c_s < 600e3
        tests.append(f"Test 1: c_s(10⁷ K) = {c_s/1e3:.0f} km/s ∈ [400, 600]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Bondi radius for Sgr A* ~ 0.01-0.1 pc
        M_SgrA = 4e6 * self.M_sun
        r_B, _ = self.compute_bondi_radius(M_SgrA, 500e3)
        r_B_pc = r_B / 3.086e16
        t2 = 0.001 < r_B_pc < 1.0
        tests.append(f"Test 2: r_B(Sgr A*) = {r_B_pc:.3f} pc ∈ [0.001, 1]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Accretion rate positive and physical
        M_dot, _ = self.compute_accretion_rate(1e8 * self.M_sun, 1e-24, T=1e7)
        t3 = 1e-8 < M_dot < 10
        tests.append(f"Test 3: Ṁ_Bondi = {M_dot:.4e} M_☉/yr ∈ [10⁻⁸, 10]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Higher density → higher accretion
        M_dot_low, _ = self.compute_accretion_rate(1e8 * self.M_sun, 1e-25, T=1e7)
        M_dot_high, _ = self.compute_accretion_rate(1e8 * self.M_sun, 1e-24, T=1e7)
        t4 = M_dot_high > M_dot_low
        tests.append(f"Test 4: Ṁ(ρ_high) > Ṁ(ρ_low): {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"BondiAccretionModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class EddingtonRatioModel:
    """
    Eddington Ratio Model - AGN Activity Indicator
    
    Models the distribution of Eddington ratios (λ = L/L_Edd) in AGN,
    indicating accretion activity levels.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Eddington Luminosity:
    L_Edd = 4π × G × M × m_p × c / σ_T ≈ 1.26 × 10³⁸ × (M/M_☉) erg/s
    
    Eddington Ratio:
    λ = L_bol / L_Edd
    
    Distribution (log-normal):
    P(λ) ∝ exp(-(log λ - μ)² / (2σ²))
    
    Where:
        L_bol : Bolometric luminosity (erg/s)
        L_Edd : Eddington luminosity
        μ : Mean of log λ (typically -1 to -2)
        σ : Standard deviation (typically 0.3-0.5)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - λ = 1: Eddington-limited accretion (maximum sustainable)
    - λ ~ 0.1: Typical luminous AGN/quasar
    - λ ~ 0.01: Moderate AGN
    - λ << 0.01: Low-luminosity AGN (LLAGN), radiatively inefficient
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        self.m_p = 1.673e-27       # Proton mass
        self.sigma_T = 6.652e-29   # Thomson cross section (m²)
        
        # Distribution parameters (typical for AGN)
        self.mu_log_lambda = -1.0   # Mean log λ (λ ~ 0.1)
        self.sigma_log_lambda = 0.4 # Dispersion
        
    def compute_eddington_luminosity(self, M: float) -> Tuple[float, str]:
        """
        Compute Eddington luminosity.
        
        Args:
            M: Black hole mass (kg)
            
        Returns:
            L_Edd: Eddington luminosity (erg/s)
            steps: Calculation explanation
        """
        # L_Edd = 4π × G × M × m_p × c / σ_T
        L_Edd_W = 4 * 3.14159 * self.G * M * self.m_p * self.c / self.sigma_T
        L_Edd = L_Edd_W * 1e7  # Convert W to erg/s
        
        steps = f"""Eddington Luminosity:
  
  L_Edd = 4π G M m_p c / σ_T
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2e} M_☉
  
  Result:
    L_Edd = {L_Edd_W:.4e} W = {L_Edd:.4e} erg/s
    
  Shortcut: L_Edd ≈ 1.26 × 10³⁸ × (M/M_☉) erg/s
            L_Edd ≈ {1.26e38 * M/self.M_sun:.4e} erg/s
"""
        return L_Edd, steps
    
    def compute_eddington_ratio(self, L_bol: float, M: float) -> Tuple[float, str]:
        """
        Compute Eddington ratio.
        
        Args:
            L_bol: Bolometric luminosity (erg/s)
            M: Black hole mass (kg)
            
        Returns:
            lambda_Edd: Eddington ratio
            steps: Calculation explanation
        """
        L_Edd, _ = self.compute_eddington_luminosity(M)
        lambda_Edd = L_bol / L_Edd
        
        if lambda_Edd > 1:
            classification = "Super-Eddington (radiation pressure dominated)"
        elif lambda_Edd > 0.1:
            classification = "High accretion rate (luminous AGN/quasar)"
        elif lambda_Edd > 0.01:
            classification = "Moderate AGN"
        elif lambda_Edd > 0.001:
            classification = "Low-luminosity AGN (LLAGN)"
        else:
            classification = "Radiatively inefficient (ADAF/RIAF)"
        
        steps = f"""Eddington Ratio:
  
  λ = L_bol / L_Edd
  
  Parameters:
    L_bol = {L_bol:.4e} erg/s
    L_Edd = {L_Edd:.4e} erg/s
  
  Result:
    λ = {lambda_Edd:.4e}
    log λ = {lambda_Edd:.4e} → log₁₀ = {__import__('math').log10(lambda_Edd) if lambda_Edd > 0 else float('-inf'):.2f}
  
  Classification: {classification}
"""
        return lambda_Edd, steps
    
    def compute_distribution_probability(self, lambda_Edd: float) -> Tuple[float, str]:
        """
        Compute probability density from log-normal distribution.
        
        Args:
            lambda_Edd: Eddington ratio
            
        Returns:
            P: Probability density
            steps: Calculation explanation
        """
        import math
        
        if lambda_Edd <= 0:
            return 0.0, "λ ≤ 0: P = 0"
        
        log_lambda = math.log10(lambda_Edd)
        exponent = -(log_lambda - self.mu_log_lambda)**2 / (2 * self.sigma_log_lambda**2)
        P = math.exp(exponent) / (lambda_Edd * self.sigma_log_lambda * math.sqrt(2*math.pi))
        
        steps = f"""Log-Normal Distribution:
  
  P(λ) ∝ exp(-(log λ - μ)² / (2σ²))
  
  Parameters:
    λ = {lambda_Edd:.4e}
    log₁₀ λ = {log_lambda:.2f}
    μ = {self.mu_log_lambda} (peak at λ ~ 0.1)
    σ = {self.sigma_log_lambda}
  
  Result:
    P(λ) = {P:.4e}
"""
        return P, steps
    
    def compute_eddington_rate(self, M: float, epsilon: float = 0.1) -> Tuple[float, str]:
        """
        Compute Eddington accretion rate.
        
        Args:
            M: Black hole mass (kg)
            epsilon: Radiative efficiency
            
        Returns:
            M_dot_Edd: Eddington rate (M_☉/yr)
            steps: Calculation explanation
        """
        L_Edd, _ = self.compute_eddington_luminosity(M)
        
        # Ṁ_Edd = L_Edd / (ε c²)
        L_Edd_W = L_Edd / 1e7  # to Watts
        M_dot_Edd_SI = L_Edd_W / (epsilon * self.c**2)
        M_dot_Edd = M_dot_Edd_SI * 3.156e7 / self.M_sun  # to M_☉/yr
        
        steps = f"""Eddington Accretion Rate:
  
  Ṁ_Edd = L_Edd / (ε c²)
  
  Parameters:
    M = {M/self.M_sun:.2e} M_☉
    L_Edd = {L_Edd:.4e} erg/s
    ε = {epsilon}
  
  Result:
    Ṁ_Edd = {M_dot_Edd:.4e} M_☉/yr
"""
        return M_dot_Edd, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Eddington Ratio Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: L_Edd for 10⁸ M_☉ ~ 10⁴⁶ erg/s
        L_Edd, _ = self.compute_eddington_luminosity(1e8 * self.M_sun)
        t1 = 1e45 < L_Edd < 1e47
        tests.append(f"Test 1: L_Edd(10⁸ M_☉) = {L_Edd:.2e} ∈ [10⁴⁵, 10⁴⁷]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: λ = 1 for L = L_Edd
        M_test = 1e7 * self.M_sun
        L_Edd_test, _ = self.compute_eddington_luminosity(M_test)
        lambda_test, _ = self.compute_eddington_ratio(L_Edd_test, M_test)
        t2 = abs(lambda_test - 1.0) < 0.01
        tests.append(f"Test 2: λ(L=L_Edd) = {lambda_test:.4f} ≈ 1: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Distribution peaks near λ ~ 0.1
        P_peak, _ = self.compute_distribution_probability(0.1)
        P_low, _ = self.compute_distribution_probability(0.001)
        t3 = P_peak > P_low
        tests.append(f"Test 3: P(λ=0.1) > P(λ=0.001): {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Eddington rate physical
        M_dot, _ = self.compute_eddington_rate(1e8 * self.M_sun)
        t4 = 1 < M_dot < 100
        tests.append(f"Test 4: Ṁ_Edd(10⁸ M_☉) = {M_dot:.2f} M_☉/yr ∈ [1, 100]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"EddingtonRatioModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class TidalDisruptionEventModel:
    """
    Tidal Disruption Event (TDE) Model
    
    Models the rate and properties of stars being torn apart by SMBHs,
    providing insights into SMBH properties and stellar dynamics.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    TDE Rate (Loss Cone Dynamics):
    Γ_TDE ≈ N_★ / τ_LC
    
    Where:
        N_★ : Number of stars in loss cone
        τ_LC : Loss cone refilling timescale
    
    Tidal Disruption Radius (from TidalForceModel):
    r_T = R_★ × (M_BH / M_★)^(1/3)
    
    Hills Mass (maximum BH mass for visible TDE):
    M_Hills ≈ 10⁸ M_☉ × (R_★/R_☉) × (M_★/M_☉)^(-1/3)
    
    OBSERVATIONAL PROPERTIES:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Peak luminosity: L_peak ~ 10⁴⁴ erg/s (Eddington for 10⁶ M_☉)
    - Timescale: t_decay ∝ t^(-5/3) (fallback rate)
    - Rate: Γ_TDE ~ 10⁻⁴ - 10⁻⁵ per galaxy per year
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        self.R_sun = 6.96e8        # Solar radius (m)
        
    def compute_disruption_radius(self, M_BH: float, M_star: float = None, 
                                   R_star: float = None) -> Tuple[float, str]:
        """
        Compute tidal disruption radius.
        
        Args:
            M_BH: Black hole mass (kg)
            M_star: Stellar mass (kg)
            R_star: Stellar radius (m)
            
        Returns:
            r_T: Disruption radius (m)
            steps: Calculation explanation
        """
        if M_star is None:
            M_star = self.M_sun
        if R_star is None:
            R_star = self.R_sun
            
        r_T = R_star * (M_BH / M_star) ** (1/3)
        r_s = 2 * self.G * M_BH / self.c**2
        
        steps = f"""Tidal Disruption Radius:
  
  r_T = R_★ × (M_BH / M_★)^(1/3)
  
  Parameters:
    M_BH = {M_BH/self.M_sun:.2e} M_☉
    M_★ = {M_star/self.M_sun:.2f} M_☉
    R_★ = {R_star/self.R_sun:.2f} R_☉
  
  Result:
    r_T = {r_T:.4e} m = {r_T/1.496e11:.4f} AU
    r_s = {r_s:.4e} m
    r_T/r_s = {r_T/r_s:.2f}
    
  {'Visible TDE: star disrupted outside horizon' if r_T > r_s else 'Direct capture: star swallowed whole'}
"""
        return r_T, steps
    
    def compute_hills_mass(self, M_star: float = None, R_star: float = None) -> Tuple[float, str]:
        """
        Compute Hills mass - maximum BH mass for visible TDE.
        
        Args:
            M_star: Stellar mass (kg)
            R_star: Stellar radius (m)
            
        Returns:
            M_Hills: Hills mass (kg)
            steps: Calculation explanation
        """
        if M_star is None:
            M_star = self.M_sun
        if R_star is None:
            R_star = self.R_sun
            
        # M_Hills ≈ 10⁸ M_☉ for solar-type star
        # Derived from r_T = r_s condition
        # M_Hills = (c²R_★/(2G))^(3/2) × M_★^(-1/2)
        M_Hills = (self.c**2 * R_star / (2 * self.G))**(3/2) * M_star**(-1/2)
        
        steps = f"""Hills Mass (Maximum for Visible TDE):
  
  M_Hills: r_T = r_s condition
  M_Hills = (c²R_★/2G)^(3/2) × M_★^(-1/2)
  
  Parameters:
    M_★ = {M_star/self.M_sun:.2f} M_☉
    R_★ = {R_star/self.R_sun:.2f} R_☉
  
  Result:
    M_Hills = {M_Hills:.4e} kg = {M_Hills/self.M_sun:.2e} M_☉
    
  For M_BH > M_Hills: star captured whole, no flare.
  For M_BH < M_Hills: visible TDE with optical/X-ray emission.
"""
        return M_Hills, steps
    
    def compute_TDE_rate(self, M_BH: float, sigma: float = 100e3) -> Tuple[float, str]:
        """
        Estimate TDE rate from velocity dispersion.
        
        Args:
            M_BH: Black hole mass (kg)
            sigma: Velocity dispersion (m/s)
            
        Returns:
            Gamma_TDE: TDE rate (per year)
            steps: Calculation explanation
        """
        import math
        
        # Loss cone theory: Γ ∝ (M_BH)^(-0.4) approximately
        # Empirical calibration: ~10⁻⁴ yr⁻¹ for 10⁶-10⁷ M_☉
        M_BH_6 = M_BH / (1e6 * self.M_sun)
        
        # Rate scaling from simulations
        Gamma_TDE = 1e-4 * M_BH_6**(-0.4)
        
        # Apply Hills mass cutoff
        M_Hills, _ = self.compute_hills_mass()
        if M_BH > M_Hills:
            Gamma_TDE = 0.0
            note = "M_BH > M_Hills: Direct capture only, no visible TDE"
        else:
            note = f"Expect ~{Gamma_TDE * 1e4:.1f} TDEs per 10,000 years"
        
        steps = f"""TDE Rate Estimation:
  
  Γ_TDE ≈ 10⁻⁴ × (M_BH/10⁶ M_☉)^(-0.4) yr⁻¹
  
  Parameters:
    M_BH = {M_BH/self.M_sun:.2e} M_☉
    M_Hills = {M_Hills/self.M_sun:.2e} M_☉
  
  Result:
    Γ_TDE = {Gamma_TDE:.4e} yr⁻¹
    
  {note}
"""
        return Gamma_TDE, steps
    
    def compute_fallback_lightcurve(self, t: float, t_min: float = 1.0) -> Tuple[float, str]:
        """
        Compute normalized fallback rate (lightcurve shape).
        
        L(t) ∝ t^(-5/3) for t > t_min
        
        Args:
            t: Time since disruption (days)
            t_min: Minimum fallback time (days)
            
        Returns:
            L_norm: Normalized luminosity [0, 1]
            steps: Calculation explanation
        """
        if t < t_min:
            L_norm = (t / t_min)  # Rising phase
        else:
            L_norm = (t / t_min)**(-5/3)  # Fallback decay
        
        steps = f"""TDE Lightcurve (Fallback Rate):
  
  L(t) ∝ t^(-5/3) for t > t_min
  
  Parameters:
    t = {t:.1f} days
    t_min = {t_min:.1f} days (peak)
  
  Result:
    L/L_peak = {L_norm:.4f}
    
  The t^(-5/3) decay is characteristic of TDE fallback dynamics.
"""
        return L_norm, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate TDE Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: r_T for Sun around 10⁶ M_☉ ~ 10¹¹ m
        r_T, _ = self.compute_disruption_radius(1e6 * self.M_sun)
        t1 = 1e10 < r_T < 1e12
        tests.append(f"Test 1: r_T(10⁶ M_☉) = {r_T:.2e} m ∈ [10¹⁰, 10¹²]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Hills mass ~ 10⁸ M_☉ for Sun
        M_H, _ = self.compute_hills_mass()
        t2 = 1e7 < M_H/self.M_sun < 1e9
        tests.append(f"Test 2: M_Hills = {M_H/self.M_sun:.2e} M_☉ ∈ [10⁷, 10⁹]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: TDE rate ~ 10⁻⁴ yr⁻¹ for typical SMBH
        Gamma, _ = self.compute_TDE_rate(1e6 * self.M_sun)
        t3 = 1e-5 < Gamma < 1e-3
        tests.append(f"Test 3: Γ_TDE = {Gamma:.2e} yr⁻¹ ∈ [10⁻⁵, 10⁻³]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Fallback decay rate t^(-5/3)
        L_10, _ = self.compute_fallback_lightcurve(10)
        L_100, _ = self.compute_fallback_lightcurve(100)
        ratio = L_10 / L_100
        expected = 10**(5/3)  # ~ 21.5
        t4 = abs(ratio - expected) / expected < 0.1
        tests.append(f"Test 4: L(10d)/L(100d) = {ratio:.2f} ≈ {expected:.2f}: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"TidalDisruptionEventModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class SMBHSpinEvolutionModel:
    """
    SMBH Spin Evolution Model - Stochastic Spin Dynamics
    
    Models the evolution of SMBH spin through accretion and mergers,
    using Langevin dynamics for stochastic torques.
    
    KEY EQUATION (Langevin):
    ─────────────────────────────────────────────────────────────────────────────
    
    da/dt = -γ × a + ξ(t)
    
    Where:
        a : Dimensionless spin parameter [-1, 1]
        γ : Damping coefficient (spin-down rate)
        ξ(t) : Random torque (stochastic forcing)
    
    For coherent accretion:
    a → a_max ≈ 0.998 (Thorne limit for thin disk)
    
    For chaotic accretion:
    ⟨a⟩ → 0 (random alignment averages out)
    
    PHYSICAL PROCESSES:
    ─────────────────────────────────────────────────────────────────────────────
    
    SPIN-UP:
    - Coherent gas accretion (aligned disk)
    - Prograde mergers
    
    SPIN-DOWN:
    - Chaotic/misaligned accretion
    - Retrograde mergers
    - Magnetic torques (Blandford-Znajek)
    
    OBSERVATIONAL CONSTRAINTS:
    - X-ray reflection spectroscopy: a ~ 0.7-0.998
    - GW binary mergers: a ~ 0.1-0.7 (pre-merger)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.a_max = 0.998         # Thorne limit
        self.a_min = -1.0          # Maximum retrograde
        
        # Timescales
        self.t_align = 1e7         # Alignment timescale (yr)
        self.t_coherent = 1e8      # Coherent accretion duration (yr)
        
    def compute_spin_up_rate(self, M_BH: float, M_disk: float, 
                              t_acc: float) -> Tuple[float, str]:
        """
        Compute spin-up rate from coherent accretion.
        
        Args:
            M_BH: Black hole mass (M_☉)
            M_disk: Disk mass being accreted (M_☉)
            t_acc: Accretion timescale (yr)
            
        Returns:
            da_dt: Spin-up rate (per year)
            steps: Calculation explanation
        """
        # Simplified: Δa ∝ ΔM/M for thin disk
        # Full expression: da/d(ln M) ≈ (l_ISCO/M) where l is specific angular momentum
        
        delta_M_ratio = M_disk / M_BH
        da_dt = delta_M_ratio / t_acc  # Approximate spin-up rate
        
        steps = f"""Spin-Up Rate (Coherent Accretion):
  
  da/dt ≈ (M_disk/M_BH) / t_acc
  
  Parameters:
    M_BH = {M_BH:.2e} M_☉
    M_disk = {M_disk:.2e} M_☉
    t_acc = {t_acc:.2e} yr
  
  Result:
    da/dt ≈ {da_dt:.4e} yr⁻¹
    
  Time to spin up from a=0 to a=0.9: ~{0.9/da_dt:.2e} yr
"""
        return da_dt, steps
    
    def compute_equilibrium_spin(self, f_coherent: float) -> Tuple[float, str]:
        """
        Compute equilibrium spin from coherent fraction.
        
        Args:
            f_coherent: Fraction of accretion that is coherent [0, 1]
            
        Returns:
            a_eq: Equilibrium spin
            steps: Calculation explanation
        """
        # If f_coherent = 1: a → a_max
        # If f_coherent = 0.5: chaotic, a → 0
        # Interpolate: a_eq = a_max × (2 × f_coherent - 1) for f > 0.5
        
        if f_coherent >= 0.5:
            a_eq = self.a_max * (2 * f_coherent - 1)
        else:
            a_eq = 0.0  # Chaotic regime
        
        steps = f"""Equilibrium Spin:
  
  For f_coherent > 0.5:
    a_eq = a_max × (2 × f_coherent - 1)
  
  Parameters:
    f_coherent = {f_coherent:.2f}
    a_max = {self.a_max}
  
  Result:
    a_eq = {a_eq:.4f}
    
  f = 1.0 → a = 0.998 (fully coherent)
  f = 0.5 → a = 0.0 (chaotic equilibrium)
  f < 0.5 → a remains low
"""
        return a_eq, steps
    
    def compute_merger_spin(self, a1: float, a2: float, q: float, 
                            theta1: float = 0, theta2: float = 0) -> Tuple[float, str]:
        """
        Estimate final spin from BH-BH merger.
        
        Args:
            a1: Primary spin [-1, 1]
            a2: Secondary spin [-1, 1]
            q: Mass ratio M2/M1 ≤ 1
            theta1, theta2: Spin-orbit misalignment angles (rad)
            
        Returns:
            a_final: Final spin estimate
            steps: Calculation explanation
        """
        import math
        
        # Simplified Rezzolla formula
        nu = q / (1 + q)**2  # Symmetric mass ratio
        
        # Equal mass, aligned spins approximation
        if q > 0.9 and abs(theta1) < 0.1 and abs(theta2) < 0.1:
            # Nearly equal mass, aligned
            a_final = 0.686 + 0.15 * (a1 + a2) - 0.05 * (a1 - a2)**2
        else:
            # General case (approximate)
            L_orb = 2 * math.sqrt(3) * nu  # Orbital angular momentum contribution
            S_eff = (a1 + q**2 * a2) / (1 + q)**2  # Effective spin
            a_final = min(self.a_max, abs(L_orb + S_eff * math.cos(theta1)))
        
        a_final = min(self.a_max, max(-1, a_final))
        
        steps = f"""Merger Final Spin (Approximate):
  
  Parameters:
    a1 = {a1:.3f}, a2 = {a2:.3f}
    q = M2/M1 = {q:.3f}
    θ1 = {theta1:.2f} rad, θ2 = {theta2:.2f} rad
    ν = q/(1+q)² = {nu:.4f}
  
  Result:
    a_final ≈ {a_final:.4f}
    
  Equal mass aligned mergers typically yield a ~ 0.7.
  High mass ratio (q << 1) preserves primary spin.
"""
        return a_final, steps
    
    def compute_radiative_efficiency(self, a: float) -> Tuple[float, str]:
        """
        Compute radiative efficiency from spin.
        
        ε = 1 - E_ISCO/c² (Novikov-Thorne)
        
        Args:
            a: Spin parameter [-1, 1]
            
        Returns:
            epsilon: Radiative efficiency
            steps: Calculation explanation
        """
        import math
        
        # ISCO radius: r_ISCO/M depends on spin
        if abs(a) < 0.01:
            epsilon = 0.057  # Schwarzschild
        elif a > 0:
            # Prograde, simplified approximation
            epsilon = 0.057 + 0.35 * a**2  # Approximate fit
        else:
            # Retrograde
            epsilon = 0.057 - 0.02 * abs(a)
        
        epsilon = min(0.42, max(0.038, epsilon))  # Physical bounds
        
        steps = f"""Radiative Efficiency (Novikov-Thorne):
  
  ε = 1 - E_ISCO (energy at ISCO)
  
  Parameters:
    a = {a:.4f}
  
  Result:
    ε = {epsilon:.4f}
    
  a = 0 (Schwarzschild): ε ≈ 0.057
  a = 0.998 (maximal): ε ≈ 0.42
  
  Higher spin → more efficient energy extraction.
"""
        return epsilon, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate SMBH Spin Evolution Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Spin-up rate positive and physical
        da_dt, _ = self.compute_spin_up_rate(1e8, 1e6, 1e7)
        t1 = 0 < da_dt < 1e-5
        tests.append(f"Test 1: da/dt = {da_dt:.2e} yr⁻¹ ∈ (0, 10⁻⁵): {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: a_eq = a_max for f_coherent = 1
        a_eq, _ = self.compute_equilibrium_spin(1.0)
        t2 = abs(a_eq - self.a_max) < 0.01
        tests.append(f"Test 2: a_eq(f=1) = {a_eq:.4f} ≈ a_max: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Equal mass merger gives a ~ 0.7-0.85
        a_merger, _ = self.compute_merger_spin(0.5, 0.5, 1.0)
        t3 = 0.6 < a_merger < 0.9
        tests.append(f"Test 3: a_merger(q=1, a=0.5) = {a_merger:.3f} ∈ [0.6, 0.9]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Efficiency increases with spin
        eps_0, _ = self.compute_radiative_efficiency(0)
        eps_high, _ = self.compute_radiative_efficiency(0.9)
        t4 = eps_high > eps_0
        tests.append(f"Test 4: ε(a=0.9) = {eps_high:.3f} > ε(a=0) = {eps_0:.3f}: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"SMBHSpinEvolutionModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


