# ═══════════════════════════════════════════════════════════════════════════════
# STELLAR AND PLANETARY MASS MODEL (M_s)
# ═══════════════════════════════════════════════════════════════════════════════

class StellarMassModel:
    """
    Stellar and Planetary Mass Model - M_s Central Body Calculations
    
    ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
    
    DEFINITION:
        M_s : Mass of the central body (star or planet) in UQFF gravitational
              calculations. Primary reference is solar mass M_☉ = 1.989×10³⁰ kg.
    
    ROLE IN UNIFIED FRAMEWORK:
        M_s appears critically in both Ug1 and Ug2 gravity terms:
        
        1. Ug1 (Internal Dipole Field):
           Contribution: ∇(M_s/r) - Gravitational gradient from central mass
           Creates internal vacuum energy density variations
           Drives [UA] field response within R_b boundary
           
        2. Ug2 (Outer Field Bubble):
           Contribution: ρ_vac × M_s/r² - Vacuum-mediated gravitational acceleration
           Gravitational acceleration modified by vacuum energy density
           Extends beyond R_b to asymptotic limit
    
    REFERENCE MASSES:
        ┌──────────────┬──────────────────────┬────────────────────────┐
        │ Body         │ Mass (kg)            │ Relative to M_☉        │
        ├──────────────┼──────────────────────┼────────────────────────┤
        │ Sun (M_☉)    │ 1.989 × 10³⁰         │ 1.0 (reference)        │
        │ Jupiter (M_♃)│ 1.898 × 10²⁷         │ 9.545 × 10⁻⁴           │
        │ Saturn       │ 5.683 × 10²⁶         │ 2.858 × 10⁻⁴           │
        │ Neptune      │ 1.024 × 10²⁶         │ 5.149 × 10⁻⁵           │
        │ Uranus       │ 8.681 × 10²⁵         │ 4.365 × 10⁻⁵           │
        │ Earth (M_⊕)  │ 5.972 × 10²⁴         │ 3.003 × 10⁻⁶           │
        │ Venus        │ 4.867 × 10²⁴         │ 2.447 × 10⁻⁶           │
        │ Mars (M_♂)   │ 6.417 × 10²³         │ 3.227 × 10⁻⁷           │
        │ Mercury (M_☿)│ 3.301 × 10²³         │ 1.660 × 10⁻⁷           │
        └──────────────┴──────────────────────┴────────────────────────┘
    
    UNIT CONVERSIONS:
        1 M_☉ = 1.989 × 10³⁰ kg
        1 M_☉ ≈ 332,946 M_⊕  (Earth masses)
        1 M_☉ ≈ 1,047 M_♃    (Jupiter masses)
    
    GRAVITATIONAL CALCULATIONS:
        At 1 AU from Sun:  a = GM_☉/r² ≈ 5.93 × 10⁻³ m/s²
        At R_b (100 AU):   M_s/r² ≈ 8.89 × 10³ kg/m²
    
    EXAMPLE CALCULATION (Ug2 at R_b = 100 AU):
        ρ_vac = 7.09 × 10⁻³⁷ J/m³ (solar scale)
        M_s = 1.989 × 10³⁰ kg
        r = R_b = 1.496 × 10¹³ m
        
        M_s/r² = 1.989×10³⁰ / (1.496×10¹³)² = 8.89 × 10³ kg/m²
        
        Ug2 contribution ∝ ρ_vac × M_s/r²
                        = 7.09×10⁻³⁷ × 8.89×10³
                        ≈ 6.30 × 10⁻³³ J/m³·kg/m²
    """
    
    # Reference masses (kg)
    MASSES = {
        'Sun': 1.989e30,
        'Jupiter': 1.898e27,
        'Saturn': 5.683e26,
        'Neptune': 1.024e26,
        'Uranus': 8.681e25,
        'Earth': 5.972e24,
        'Venus': 4.867e24,
        'Mars': 6.417e23,
        'Mercury': 3.301e23,
    }
    
    # Mean orbital radii (m) - for gravitational calculations
    ORBITAL_RADII = {
        'Mercury': 5.79e10,
        'Venus': 1.082e11,
        'Earth': 1.496e11,   # 1 AU
        'Mars': 2.279e11,
        'Jupiter': 7.785e11,
        'Saturn': 1.432e12,
        'Uranus': 2.867e12,
        'Neptune': 4.515e12,
    }
    
    def __init__(self, M_s: float = None, body_name: str = 'Sun'):
        """
        Initialize stellar mass model.
        
        Args:
            M_s: Mass in kg (overrides body_name if provided)
            body_name: Name of body to use mass from MASSES dict
        """
        if M_s is not None:
            self.M_s = M_s
            self.body_name = 'Custom'
        else:
            self.M_s = self.MASSES.get(body_name, self.MASSES['Sun'])
            self.body_name = body_name
        
        self.M_sun = 1.989e30
        self.G = 6.674e-11  # Gravitational constant m³/(kg·s²)
        self.AU = 1.496e11  # Astronomical unit (m)
    
    def mass_in_solar_units(self, M_kg: float = None) -> float:
        """Convert mass from kg to solar masses."""
        M = M_kg if M_kg is not None else self.M_s
        return M / self.M_sun
    
    def mass_in_earth_units(self, M_kg: float = None) -> float:
        """Convert mass from kg to Earth masses."""
        M = M_kg if M_kg is not None else self.M_s
        return M / self.MASSES['Earth']
    
    def mass_in_jupiter_units(self, M_kg: float = None) -> float:
        """Convert mass from kg to Jupiter masses."""
        M = M_kg if M_kg is not None else self.M_s
        return M / self.MASSES['Jupiter']
    
    def solar_masses_to_kg(self, M_solar: float) -> float:
        """Convert solar masses to kg."""
        return M_solar * self.M_sun
    
    def earth_masses_to_kg(self, M_earth: float) -> float:
        """Convert Earth masses to kg."""
        return M_earth * self.MASSES['Earth']
    
    def jupiter_masses_to_kg(self, M_jupiter: float) -> float:
        """Convert Jupiter masses to kg."""
        return M_jupiter * self.MASSES['Jupiter']
    
    def gravitational_acceleration(self, r: float, M_s: float = None) -> float:
        """
        Calculate gravitational acceleration at distance r.
        
        Args:
            r: Distance from center (m)
            M_s: Central mass (kg), defaults to self.M_s
            
        Returns:
            Gravitational acceleration (m/s²)
        """
        M = M_s if M_s is not None else self.M_s
        return self.G * M / (r ** 2)
    
    def mass_over_r_squared(self, r: float, M_s: float = None) -> float:
        """
        Calculate M_s/r² term used in Ug2.
        
        Args:
            r: Distance from center (m)
            M_s: Central mass (kg), defaults to self.M_s
            
        Returns:
            M_s/r² (kg/m²)
        """
        M = M_s if M_s is not None else self.M_s
        return M / (r ** 2)
    
    def gravitational_gradient(self, r: float, M_s: float = None) -> float:
        """
        Calculate ∇(M_s/r) gravitational gradient term used in Ug1.
        
        For radial direction: d/dr(M_s/r) = -M_s/r²
        
        Args:
            r: Distance from center (m)
            M_s: Central mass (kg), defaults to self.M_s
            
        Returns:
            -M_s/r² (kg/m²) - negative indicates inward gradient
        """
        M = M_s if M_s is not None else self.M_s
        return -M / (r ** 2)
    
    def Ug2_contribution(self, r: float, rho_vac: float = 7.09e-37, 
                         M_s: float = None) -> dict:
        """
        Calculate Ug2 contribution from central mass.
        
        Ug2 ∝ ρ_vac × M_s/r²
        
        Args:
            r: Distance from center (m)
            rho_vac: Vacuum energy density (J/m³)
            M_s: Central mass (kg), defaults to self.M_s
            
        Returns:
            Dict with calculation details
        """
        M = M_s if M_s is not None else self.M_s
        
        M_over_r2 = M / (r ** 2)
        contribution = rho_vac * M_over_r2
        
        return {
            'M_s': M,
            'r': r,
            'rho_vac': rho_vac,
            'M_s_over_r2': M_over_r2,
            'Ug2_contribution': contribution,
            'units': 'J·kg/(m⁵)',
        }
    
    def validate_solar_at_1AU(self) -> dict:
        """
        Validate gravitational acceleration at 1 AU from Sun.
        Expected: a ≈ 5.93 × 10⁻³ m/s²
        """
        r = self.AU  # 1 AU
        a_computed = self.gravitational_acceleration(r, self.M_sun)
        a_expected = 5.93e-3  # m/s²
        
        return {
            'r': r,
            'M_s': self.M_sun,
            'a_computed': a_computed,
            'a_expected': a_expected,
            'ratio': a_computed / a_expected,
            'validation_passed': abs(a_computed / a_expected - 1.0) < 0.01,
        }
    
    def validate_Ms_r2_at_Rb(self, R_b: float = 1.496e13) -> dict:
        """
        Validate M_s/r² at R_b boundary.
        For R_b = 100 AU, expected: M_s/r² ≈ 8.89 × 10³ kg/m²
        """
        Ms_r2_computed = self.mass_over_r_squared(R_b, self.M_sun)
        Ms_r2_expected = 8.89e3  # kg/m²
        
        return {
            'R_b': R_b,
            'R_b_AU': R_b / self.AU,
            'M_s': self.M_sun,
            'Ms_r2_computed': Ms_r2_computed,
            'Ms_r2_expected': Ms_r2_expected,
            'ratio': Ms_r2_computed / Ms_r2_expected,
            'validation_passed': abs(Ms_r2_computed / Ms_r2_expected - 1.0) < 0.01,
        }
    
    def get_mass_comparison(self) -> str:
        """Return formatted table of planetary mass comparisons."""
        lines = [
            "═" * 70,
            "STELLAR AND PLANETARY MASS COMPARISON",
            "═" * 70,
            "",
            f"{'Body':<12} {'Mass (kg)':<18} {'M/M_☉':<15} {'M/M_⊕':<15}",
            "-" * 70,
        ]
        
        for body, mass in self.MASSES.items():
            M_solar = mass / self.M_sun
            M_earth = mass / self.MASSES['Earth']
            lines.append(f"{body:<12} {mass:<18.3e} {M_solar:<15.4e} {M_earth:<15.2f}")
        
        lines.extend(["", "═" * 70])
        return '\n'.join(lines)
    
    def get_summary(self) -> str:
        """Return comprehensive summary of M_s model."""
        val_1AU = self.validate_solar_at_1AU()
        val_Rb = self.validate_Ms_r2_at_Rb()
        
        return f"""
═══════════════════════════════════════════════════════════════════════════════
 STELLAR MASS MODEL (M_s) - SUMMARY
═══════════════════════════════════════════════════════════════════════════════

 CURRENT BODY: {self.body_name}
   M_s = {self.M_s:.4e} kg
       = {self.mass_in_solar_units():.4e} M_☉
       = {self.mass_in_earth_units():.2f} M_⊕
       = {self.mass_in_jupiter_units():.4f} M_♃

 ROLE IN UQFF EQUATIONS:
 
   1. Ug1 (Internal Dipole Field):
      Contribution: ∇(M_s/r) = -M_s/r²
      At r = 1 AU: ∇(M_s/r) = {self.gravitational_gradient(self.AU):.4e} kg/m²
      
   2. Ug2 (Outer Field Bubble):
      Contribution: ρ_vac × M_s/r²
      At R_b = 100 AU: M_s/r² = {self.mass_over_r_squared(1.496e13):.4e} kg/m²

 VALIDATION RESULTS:
 
   Gravitational acceleration at 1 AU:
     Computed: {val_1AU['a_computed']:.4e} m/s²
     Expected: {val_1AU['a_expected']:.4e} m/s²
     Ratio: {val_1AU['ratio']:.4f}
     Status: {'PASSED ✓' if val_1AU['validation_passed'] else 'FAILED ✗'}
   
   M_s/r² at R_b = 100 AU:
     Computed: {val_Rb['Ms_r2_computed']:.4e} kg/m²
     Expected: {val_Rb['Ms_r2_expected']:.4e} kg/m²
     Ratio: {val_Rb['ratio']:.4f}
     Status: {'PASSED ✓' if val_Rb['validation_passed'] else 'FAILED ✗'}

───────────────────────────────────────────────────────────────────────────────
 ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
═══════════════════════════════════════════════════════════════════════════════
"""


# Global Stellar Mass model instance (default: Sun)
STELLAR_MASS_MODEL = StellarMassModel()


# ═══════════════════════════════════════════════════════════════════════════════
# STELLAR AND PLANETARY ROTATION MODEL (ω_s)
# ═══════════════════════════════════════════════════════════════════════════════

class StellarRotationModel:
    """
    Stellar and Planetary Rotation Model - ω_s Dynamics
    
    ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
    
    DEFINITION:
        ω_s : Angular velocity (rotation rate) of a celestial body about its axis
        Units: rad/s (radians per second)
        Period: T = 2π/ω_s (seconds)
    
    ROLE IN UNIFIED FRAMEWORK:
        ω_s appears in two key equations:
        
        1. Ug3 (Magnetic Strings Disk):
           U_g3 = k_3 × Σ_j B_j × cos(ω_s × t × π) × P_core × E_react
           
           The term cos(ω_s × t × π) introduces oscillatory behavior:
           - Oscillation period: T_osc = 2/ω_s ≈ 9.26 days for Sun
           - Models periodic variations in gravitational field
           - Reflects rotation of magnetic strings' fields
        
        2. Universal Inertia (U_i):
           U_i = λ_i × ρ_SCm × ρ_UA × ω_s(t) × cos(πt_n) × (1 + f_TRZ)
           
           ω_s directly scales inertial resistance:
           - Higher rotation → greater resistance to change
           - Affects angular momentum in collapse/formation
           - Modulates star formation dynamics
    
    REFERENCE VALUES:
        ┌──────────────┬──────────────────────┬────────────────────────┐
        │ Body         │ ω_s (rad/s)          │ Period                 │
        ├──────────────┼──────────────────────┼────────────────────────┤
        │ Sun          │ 2.5 × 10⁻⁶           │ ~29.1 days (average)   │
        │ Mercury      │ 1.24 × 10⁻⁶          │ ~58.6 days             │
        │ Venus        │ -2.99 × 10⁻⁷         │ ~243 days (retrograde) │
        │ Earth        │ 7.29 × 10⁻⁵          │ ~24 hours              │
        │ Mars         │ 7.09 × 10⁻⁵          │ ~24.6 hours            │
        │ Jupiter      │ 1.76 × 10⁻⁴          │ ~9.93 hours            │
        │ Saturn       │ 1.64 × 10⁻⁴          │ ~10.7 hours            │
        │ Uranus       │ -1.01 × 10⁻⁴         │ ~17.2 hours (retro)    │
        │ Neptune      │ 1.08 × 10⁻⁴          │ ~16.1 hours            │
        └──────────────┴──────────────────────┴────────────────────────┘
    
    DIFFERENTIAL ROTATION (SUN):
        The Sun exhibits differential rotation (latitude-dependent):
        - Equator: ~25.0 days (ω_s ≈ 2.9 × 10⁻⁶ rad/s)
        - 30° latitude: ~26.5 days
        - 60° latitude: ~30.8 days
        - Poles: ~35.0 days (ω_s ≈ 2.1 × 10⁻⁶ rad/s)
        
        Framework uses average: 2.5 × 10⁻⁶ rad/s (~29 days)
    
    EXAMPLE CALCULATIONS:
    
        Sun at t=0, t_n=0:
        
        1. Ug3 oscillation term:
           cos(ω_s × t × π) = cos(2.5×10⁻⁶ × 0 × π) = cos(0) = 1
           
        2. U_i contribution:
           U_i = 1.0 × 7.09×10⁻³⁷ × 7.09×10⁻³⁶ × 2.5×10⁻⁶ × 1 × 1.1
               = 1.38×10⁻⁴⁷ J/m³
    """
    
    # Reference rotation rates (rad/s)
    ROTATION_RATES = {
        'Sun': 2.5e-6,
        'Mercury': 1.24e-6,
        'Venus': -2.99e-7,      # Negative = retrograde
        'Earth': 7.29e-5,
        'Mars': 7.09e-5,
        'Jupiter': 1.76e-4,
        'Saturn': 1.64e-4,
        'Uranus': -1.01e-4,     # Negative = retrograde
        'Neptune': 1.08e-4,
    }
    
    # Solar differential rotation coefficients
    # ω(θ) = A + B×sin²(θ) + C×sin⁴(θ) where θ = latitude
    # Coefficients from Howard & Harvey (1970), Snodgrass (1983)
    SOLAR_DIFF_ROTATION = {
        'A': 2.972e-6,   # Equatorial rate (rad/s)
        'B': -0.484e-6,  # sin²(θ) coefficient
        'C': -0.361e-6,  # sin⁴(θ) coefficient
    }
    
    def __init__(self, omega_s: float = None, body_name: str = 'Sun'):
        """
        Initialize stellar rotation model.
        
        Args:
            omega_s: Angular velocity in rad/s (overrides body_name if provided)
            body_name: Name of body to use rotation rate from ROTATION_RATES
        """
        if omega_s is not None:
            self.omega_s = omega_s
            self.body_name = 'Custom'
        else:
            self.omega_s = self.ROTATION_RATES.get(body_name, self.ROTATION_RATES['Sun'])
            self.body_name = body_name
    
    def period_seconds(self, omega_s: float = None) -> float:
        """Calculate rotation period in seconds: T = 2π/|ω_s|"""
        omega = omega_s if omega_s is not None else self.omega_s
        return 2 * np.pi / abs(omega)
    
    def period_days(self, omega_s: float = None) -> float:
        """Calculate rotation period in days."""
        return self.period_seconds(omega_s) / 86400
    
    def period_hours(self, omega_s: float = None) -> float:
        """Calculate rotation period in hours."""
        return self.period_seconds(omega_s) / 3600
    
    def is_retrograde(self, omega_s: float = None) -> bool:
        """Check if rotation is retrograde (negative ω_s)."""
        omega = omega_s if omega_s is not None else self.omega_s
        return omega < 0
    
    def omega_from_period_days(self, T_days: float) -> float:
        """Calculate ω_s from period in days."""
        T_seconds = T_days * 86400
        return 2 * np.pi / T_seconds
    
    def omega_from_period_hours(self, T_hours: float) -> float:
        """Calculate ω_s from period in hours."""
        T_seconds = T_hours * 3600
        return 2 * np.pi / T_seconds
    
    def Ug3_oscillation_term(self, t: float, omega_s: float = None) -> float:
        """
        Calculate Ug3 oscillation term: cos(ω_s × t × π)
        
        Args:
            t: Time in seconds
            omega_s: Angular velocity (rad/s)
            
        Returns:
            cos(ω_s × t × π) value in range [-1, 1]
        """
        omega = omega_s if omega_s is not None else self.omega_s
        return np.cos(omega * t * np.pi)
    
    def Ug3_oscillation_period_seconds(self, omega_s: float = None) -> float:
        """
        Calculate period of Ug3 oscillation: cos(ω_s × t × π)
        
        Period: ω_s × t × π = 2π → t = 2/ω_s
        """
        omega = omega_s if omega_s is not None else self.omega_s
        return 2 / abs(omega)
    
    def Ug3_oscillation_period_days(self, omega_s: float = None) -> float:
        """Calculate Ug3 oscillation period in days."""
        return self.Ug3_oscillation_period_seconds(omega_s) / 86400
    
    def solar_differential_omega(self, latitude_deg: float) -> float:
        """
        Calculate Sun's rotation rate at given latitude.
        
        Uses differential rotation formula:
        ω(θ) = A + B×sin²(θ) + C×sin⁴(θ)
        
        Args:
            latitude_deg: Heliographic latitude in degrees (0 = equator, 90 = pole)
            
        Returns:
            ω_s in rad/s at that latitude
        """
        theta = np.radians(latitude_deg)
        A = self.SOLAR_DIFF_ROTATION['A']
        B = self.SOLAR_DIFF_ROTATION['B']
        C = self.SOLAR_DIFF_ROTATION['C']
        
        sin2 = np.sin(theta) ** 2
        sin4 = sin2 ** 2
        
        return A + B * sin2 + C * sin4
    
    def solar_differential_period(self, latitude_deg: float) -> float:
        """Calculate Sun's rotation period at given latitude (in days)."""
        omega = self.solar_differential_omega(latitude_deg)
        return 2 * np.pi / omega / 86400
    
    def validate_sun_rotation(self) -> dict:
        """Validate Sun rotation parameters against document."""
        omega_sun = self.ROTATION_RATES['Sun']
        T_days = self.period_days(omega_sun)
        T_expected = 29.1  # days
        
        T_Ug3_days = self.Ug3_oscillation_period_days(omega_sun)
        T_Ug3_expected = 9.26  # days
        
        return {
            'omega_s': omega_sun,
            'period_days': T_days,
            'period_expected': T_expected,
            'period_ratio': T_days / T_expected,
            'period_match': abs(T_days / T_expected - 1.0) < 0.01,
            'Ug3_oscillation_days': T_Ug3_days,
            'Ug3_oscillation_expected': T_Ug3_expected,
            'Ug3_oscillation_ratio': T_Ug3_days / T_Ug3_expected,
            'Ug3_match': abs(T_Ug3_days / T_Ug3_expected - 1.0) < 0.01,
        }
    
    def get_rotation_comparison(self) -> str:
        """Return formatted table of planetary rotation comparisons."""
        lines = [
            "═" * 70,
            "STELLAR AND PLANETARY ROTATION COMPARISON",
            "═" * 70,
            "",
            f"{'Body':<12} {'ω_s (rad/s)':<15} {'Period':<15} {'Notes':<20}",
            "-" * 70,
        ]
        
        for body, omega in self.ROTATION_RATES.items():
            if abs(omega) < 1e-5:  # Slow rotators - period in days
                period = f"{self.period_days(omega):.1f} days"
            else:  # Fast rotators - period in hours
                period = f"{self.period_hours(omega):.2f} hours"
            
            notes = "retrograde" if omega < 0 else ""
            lines.append(f"{body:<12} {omega:<15.3e} {period:<15} {notes:<20}")
        
        lines.extend(["", "═" * 70])
        return '\n'.join(lines)
    
    def get_summary(self) -> str:
        """Return comprehensive summary of ω_s model."""
        val = self.validate_sun_rotation()
        
        return f"""
═══════════════════════════════════════════════════════════════════════════════
 STELLAR ROTATION MODEL (ω_s) - SUMMARY
═══════════════════════════════════════════════════════════════════════════════

 CURRENT BODY: {self.body_name}
   ω_s = {self.omega_s:.4e} rad/s
   Period = {self.period_days():.2f} days ({self.period_hours():.2f} hours)
   Retrograde: {self.is_retrograde()}

 ROLE IN UQFF EQUATIONS:
 
   1. Ug3 (Magnetic Strings Disk):
      cos(ω_s × t × π) at t=0: {self.Ug3_oscillation_term(0):.4f}
      Oscillation period: {self.Ug3_oscillation_period_days():.2f} days
      
   2. Universal Inertia (U_i):
      ω_s scales inertial resistance directly

 SUN VALIDATION RESULTS:
 
   Rotation period:
     Computed: {val['period_days']:.2f} days
     Expected: {val['period_expected']:.2f} days
     Ratio: {val['period_ratio']:.4f}
     Status: {'PASSED ✓' if val['period_match'] else 'FAILED ✗'}
   
   Ug3 oscillation period:
     Computed: {val['Ug3_oscillation_days']:.2f} days
     Expected: {val['Ug3_oscillation_expected']:.2f} days
     Ratio: {val['Ug3_oscillation_ratio']:.4f}
     Status: {'PASSED ✓' if val['Ug3_match'] else 'FAILED ✗'}

 SOLAR DIFFERENTIAL ROTATION:
   Equator (0°):  ω = {self.solar_differential_omega(0):.4e} rad/s → {self.solar_differential_period(0):.1f} days
   30° latitude:  ω = {self.solar_differential_omega(30):.4e} rad/s → {self.solar_differential_period(30):.1f} days
   60° latitude:  ω = {self.solar_differential_omega(60):.4e} rad/s → {self.solar_differential_period(60):.1f} days
   Pole (90°):    ω = {self.solar_differential_omega(90):.4e} rad/s → {self.solar_differential_period(90):.1f} days

───────────────────────────────────────────────────────────────────────────────
 ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
═══════════════════════════════════════════════════════════════════════════════
"""


# Global Stellar Rotation model instance (default: Sun)
STELLAR_ROTATION_MODEL = StellarRotationModel()


# ═══════════════════════════════════════════════════════════════════════════════
# SURFACE MAGNETIC FIELD MODEL (B_s)
# ═══════════════════════════════════════════════════════════════════════════════

class SurfaceMagneticFieldModel:
    """
    Surface Magnetic Field Model (B_s)
    
    Models the surface magnetic field of celestial bodies, from planets
    to magnetars. Provides B_j scaling for Ug3 calculations and unit
    conversions between Tesla and Gauss.
    
    DOCUMENT SPECIFICATION:
    ─────────────────────────────────────────────────────────────────────────
    B_s = Surface magnetic field (10⁻⁴ to 0.4 T for Sun)
    
    • Quiet Sun: ~10⁻⁴ T (1 G, 0.1 mT)
    • Sunspots: 0.1-0.4 T (1000-4000 G)
    • Earth: 25-65 μT (2.5×10⁻⁵ to 6.5×10⁻⁵ T)
    • Jupiter: ~428 μT (4.28×10⁻⁴ T)
    
    ROLE IN FRAMEWORK:
    ─────────────────────────────────────────────────────────────────────────
    • Listed in F_U arguments: Ug_i(r, t, M_s, ω_s, T_s, B_s, ...)
    • Influences B_j (magnetic string field) in Ug3
    • B_j scaling: B_j = (10³ + 0.4·sin(ω_c·t)) × B_s/B_s_ref
    
    UNITS:
    ─────────────────────────────────────────────────────────────────────────
    • Tesla (T): SI unit, T = kg/(A·s²)
    • Gauss (G): CGS unit, 1 T = 10⁴ G
    • Microtesla (μT): 1 μT = 10⁻⁶ T
    
    ───────────────────────────────────────────────────────────────────────────────
     ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
    ═══════════════════════════════════════════════════════════════════════════════
    """
    
    def __init__(self, body: str = 'Sun'):
        """
        Initialize Surface Magnetic Field Model for a celestial body.
        
        Args:
            body: Name of celestial body ('Sun', 'Earth', 'Jupiter', etc.)
        """
        self.body = body
        
        # Load B_s constants from CONSTANTS
        self.B_s_Sun = CONSTANTS.get('B_s_Sun', 1e-4)
        self.B_s_min = CONSTANTS.get('B_s_min', 1e-4)
        self.B_s_max = CONSTANTS.get('B_s_max', 0.4)
        self.B_s_quiet = CONSTANTS.get('B_s_quiet', 1e-4)
        self.B_s_sunspot = CONSTANTS.get('B_s_sunspot', 0.4)
        self.B_s_ref = CONSTANTS.get('B_s_ref', 0.4)
        
        # Planetary values
        self.B_s_Earth = CONSTANTS.get('B_s_Earth', 5e-5)
        self.B_s_Earth_min = CONSTANTS.get('B_s_Earth_min', 2.5e-5)
        self.B_s_Earth_max = CONSTANTS.get('B_s_Earth_max', 6.5e-5)
        self.B_s_Jupiter = CONSTANTS.get('B_s_Jupiter', 4.28e-4)
        self.B_s_Saturn = CONSTANTS.get('B_s_Saturn', 2.1e-5)
        self.B_s_Uranus = CONSTANTS.get('B_s_Uranus', 2.3e-5)
        self.B_s_Neptune = CONSTANTS.get('B_s_Neptune', 1.4e-5)
        self.B_s_Mercury = CONSTANTS.get('B_s_Mercury', 3e-7)
        self.B_s_Mars = CONSTANTS.get('B_s_Mars', 0.0)
        self.B_s_Venus = CONSTANTS.get('B_s_Venus', 0.0)
        
        # Extreme objects
        self.B_s_white_dwarf = CONSTANTS.get('B_s_white_dwarf', 1e3)
        self.B_s_neutron_star = CONSTANTS.get('B_s_neutron_star', 1e8)
        self.B_s_magnetar = CONSTANTS.get('B_s_magnetar', 1e11)
        
        # Solar cycle parameters
        self.omega_c = CONSTANTS.get('omega_c', 1.587e-8)
        self.mu_j_base = CONSTANTS.get('mu_j_base', 1e3)
        self.mu_j_amplitude = CONSTANTS.get('mu_j_amplitude', 0.4)
        
        # Set current body's B_s
        self.B_s = self._get_B_s_for_body(body)
    
    def _get_B_s_for_body(self, body: str) -> float:
        """
        Get surface magnetic field for the specified body.
        
        Args:
            body: Name of celestial body
            
        Returns:
            Surface magnetic field B_s in tesla
        """
        body_map = {
            'Sun': self.B_s_Sun,
            'Earth': self.B_s_Earth,
            'Jupiter': self.B_s_Jupiter,
            'Saturn': self.B_s_Saturn,
            'Uranus': self.B_s_Uranus,
            'Neptune': self.B_s_Neptune,
            'Mercury': self.B_s_Mercury,
            'Mars': self.B_s_Mars,
            'Venus': self.B_s_Venus,
            'WhiteDwarf': self.B_s_white_dwarf,
            'NeutronStar': self.B_s_neutron_star,
            'Magnetar': self.B_s_magnetar,
        }
        return body_map.get(body, self.B_s_Sun)
    
    # ═══════════════════════════════════════════════════════════════════════════
    # UNIT CONVERSION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def tesla_to_gauss(self, B_tesla: float) -> float:
        """
        Convert magnetic field from Tesla to Gauss.
        
        Args:
            B_tesla: Magnetic field in tesla (T)
            
        Returns:
            Magnetic field in gauss (G)
            
        Conversion:
            1 T = 10⁴ G
        """
        return B_tesla * 1e4
    
    def gauss_to_tesla(self, B_gauss: float) -> float:
        """
        Convert magnetic field from Gauss to Tesla.
        
        Args:
            B_gauss: Magnetic field in gauss (G)
            
        Returns:
            Magnetic field in tesla (T)
            
        Conversion:
            1 G = 10⁻⁴ T
        """
        return B_gauss * 1e-4
    
    def tesla_to_microtesla(self, B_tesla: float) -> float:
        """
        Convert Tesla to microtesla.
        
        Args:
            B_tesla: Magnetic field in tesla (T)
            
        Returns:
            Magnetic field in microtesla (μT)
        """
        return B_tesla * 1e6
    
    def microtesla_to_tesla(self, B_uT: float) -> float:
        """
        Convert microtesla to Tesla.
        
        Args:
            B_uT: Magnetic field in microtesla (μT)
            
        Returns:
            Magnetic field in tesla (T)
        """
        return B_uT * 1e-6
    
    # ═══════════════════════════════════════════════════════════════════════════
    # B_j MAGNETIC STRING FIELD METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def compute_B_j_factor(self, t: float = 0.0) -> float:
        """
        Compute the time-dependent B_j factor.
        
        Document specification:
            B_j factor = (10³ + 0.4·sin(ω_c·t))
        
        At t=0: B_j factor = 10³ = 1000
        
        Args:
            t: Time in seconds
            
        Returns:
            B_j factor (unitless)
        """
        return self.mu_j_base + self.mu_j_amplitude * np.sin(self.omega_c * t)
    
    def compute_B_j_scaled(self, B_s: float = None, t: float = 0.0) -> float:
        """
        Compute B_j scaled by surface magnetic field.
        
        Document specification (extended):
            B_j(r, θ, t, ρ_vac,[SCm]) ≈ (10³ + 0.4·sin(ω_c·t)) × B_s/B_s_ref
        
        This relates the magnetic string field B_j to the surface field B_s.
        
        Args:
            B_s: Surface magnetic field (T). If None, use current body's B_s.
            t: Time in seconds
            
        Returns:
            Scaled B_j in tesla
        """
        if B_s is None:
            B_s = self.B_s
        
        B_j_factor = self.compute_B_j_factor(t)
        return B_j_factor * (B_s / self.B_s_ref)
    
    def compute_B_j_oscillated(self, omega_s: float, t: float, B_j: float) -> float:
        """
        Compute B_j with Ug3 oscillation factor.
        
        Used in Ug3: cos(ω_s × t × π)
        
        Args:
            omega_s: Stellar rotation rate (rad/s)
            t: Time in seconds
            B_j: Magnetic string field (T)
            
        Returns:
            B_j × cos(ω_s × t × π) in tesla
        """
        oscillation = np.cos(omega_s * t * np.pi)
        return B_j * oscillation
    
    # ═══════════════════════════════════════════════════════════════════════════
    # SOLAR VARIABILITY METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def get_solar_activity_level(self, B_s: float) -> str:
        """
        Determine solar activity level based on B_s value.
        
        Args:
            B_s: Surface magnetic field in tesla
            
        Returns:
            Activity level string: 'quiet', 'moderate', or 'active'
        """
        if B_s <= 1e-4:
            return 'quiet'
        elif B_s <= 0.1:
            return 'moderate'
        else:
            return 'active'
    
    def interpolate_solar_B_s(self, activity_fraction: float) -> float:
        """
        Interpolate B_s between quiet Sun and sunspot values.
        
        Args:
            activity_fraction: 0.0 = quiet Sun, 1.0 = maximum sunspot
            
        Returns:
            Interpolated B_s in tesla
        """
        # Logarithmic interpolation (covers 4 orders of magnitude)
        log_min = np.log10(self.B_s_min)
        log_max = np.log10(self.B_s_max)
        log_B = log_min + activity_fraction * (log_max - log_min)
        return 10**log_B
    
    # ═══════════════════════════════════════════════════════════════════════════
    # UG3 CONTRIBUTION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def Ug3_B_field_contribution(self, n_layers: int = 26, t: float = 0.0) -> dict:
        """
        Compute the magnetic field contribution to Ug3.
        
        Uses 26 nested B-field layers with decreasing strength.
        
        Ug3 = k_3 × Σ_j[B_j] × cos(ω_s×t×π) × P_core × E_react
        
        This method computes the Σ_j[B_j] part.
        
        Args:
            n_layers: Number of magnetic field layers (default: 26)
            t: Time in seconds
            
        Returns:
            Dictionary with B_sum, layer contributions, and details
        """
        B_base = self.compute_B_j_scaled(self.B_s, t)
        
        # Generate 26 layers with decreasing strength
        B_layers = [B_base / (j + 1) for j in range(n_layers)]
        B_sum = sum(B_layers)
        
        return {
            'B_sum': B_sum,
            'B_base': B_base,
            'B_s': self.B_s,
            'B_s_ref': self.B_s_ref,
            'n_layers': n_layers,
            'B_layers': B_layers[:5],  # First 5 for display
            'unit': 'T'
        }
    
    # ═══════════════════════════════════════════════════════════════════════════
    # VALIDATION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def validate_B_s_range(self, B_s: float, body: str = 'Sun') -> dict:
        """
        Validate that B_s is within expected range for the given body.
        
        Args:
            B_s: Surface magnetic field to validate (T)
            body: Celestial body name
            
        Returns:
            Validation result dictionary
        """
        if body == 'Sun':
            B_min, B_max = self.B_s_min, self.B_s_max
        elif body == 'Earth':
            B_min, B_max = self.B_s_Earth_min, self.B_s_Earth_max
        else:
            # Default: allow any positive value
            B_min, B_max = 0.0, 1e15
        
        in_range = B_min <= B_s <= B_max
        
        return {
            'valid': in_range,
            'B_s': B_s,
            'B_min': B_min,
            'B_max': B_max,
            'body': body,
            'message': f"B_s = {B_s:.2e} T is {'within' if in_range else 'outside'} range [{B_min:.2e}, {B_max:.2e}] T"
        }
    
    def validate_earth_field(self) -> dict:
        """
        Validate Earth's surface magnetic field against document values.
        
        Document specification:
            Earth: 25-65 μT (2.5×10⁻⁵ to 6.5×10⁻⁵ T)
        
        Returns:
            Validation result dictionary
        """
        expected_min = 2.5e-5  # 25 μT
        expected_max = 6.5e-5  # 65 μT
        
        return {
            'B_s_Earth': self.B_s_Earth,
            'B_s_Earth_uT': self.tesla_to_microtesla(self.B_s_Earth),
            'expected_min': expected_min,
            'expected_max': expected_max,
            'in_range': expected_min <= self.B_s_Earth <= expected_max,
            'ratio_to_min': self.B_s_Earth / expected_min,
            'ratio_to_max': self.B_s_Earth / expected_max
        }
    
    def validate_sun_field(self) -> dict:
        """
        Validate Sun's surface magnetic field against document values.
        
        Document specification:
            Sun: 10⁻⁴ to 0.4 T (quiet to sunspot)
        
        Returns:
            Validation result dictionary
        """
        expected_quiet = 1e-4  # 1 G
        expected_sunspot = 0.4  # 4000 G
        
        return {
            'B_s_quiet': self.B_s_quiet,
            'B_s_quiet_gauss': self.tesla_to_gauss(self.B_s_quiet),
            'B_s_sunspot': self.B_s_sunspot,
            'B_s_sunspot_gauss': self.tesla_to_gauss(self.B_s_sunspot),
            'expected_quiet': expected_quiet,
            'expected_sunspot': expected_sunspot,
            'quiet_valid': self.B_s_quiet == expected_quiet,
            'sunspot_valid': self.B_s_sunspot == expected_sunspot
        }


"""
───────────────────────────────────────────────────────────────────────────────
 SURFACE MAGNETIC FIELD MODEL - GLOBAL INSTANCE
───────────────────────────────────────────────────────────────────────────────
 ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
═══════════════════════════════════════════════════════════════════════════════
"""


# Global Surface Magnetic Field model instance (default: Sun)
SURFACE_MAGNETIC_MODEL = SurfaceMagneticFieldModel()


# ═══════════════════════════════════════════════════════════════════════════════
# SURFACE TEMPERATURE MODEL (T_s)
# ═══════════════════════════════════════════════════════════════════════════════

class SurfaceTemperatureModel:
    """
    Surface Temperature Model (T_s)
    
    Models the surface/effective temperature of celestial bodies, providing
    Stefan-Boltzmann law calculations, Wien's law peak wavelength, and
    spectral classification utilities.
    
    DOCUMENT SPECIFICATION:
    ─────────────────────────────────────────────────────────────────────────
    T_s = Surface temperature (5778 K for Sun)
    
    • Effective photospheric temperature
    • Derived from Stefan-Boltzmann: L = 4πR²σT⁴
    • Wien's law: λ_max = b/T ≈ 501 nm (green)
    
    ROLE IN FRAMEWORK:
    ─────────────────────────────────────────────────────────────────────────
    • Listed in F_U arguments: Ug_i(r, t, M_s, ω_s, T_s, B_s, ...)
    • Implicit influence on magnetic field generation (dynamo)
    • Affects radiation pressure in nebular dynamics
    
    UNITS:
    ─────────────────────────────────────────────────────────────────────────
    • Kelvin (K): SI unit for thermodynamic temperature
    • °C = K - 273.15 (Celsius conversion)
    
    ───────────────────────────────────────────────────────────────────────────────
     ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
    ═══════════════════════════════════════════════════════════════════════════════
    """
    
    def __init__(self, body: str = 'Sun'):
        """
        Initialize Surface Temperature Model for a celestial body.
        
        Args:
            body: Name of celestial body ('Sun', 'Earth', 'Jupiter', etc.)
        """
        self.body = body
        
        # Load T_s constants
        self.T_s_Sun = CONSTANTS.get('T_s_Sun', 5778)
        self.T_s_ref = CONSTANTS.get('T_s_ref', 5778)
        
        # Stefan-Boltzmann constants
        self.sigma_sb = CONSTANTS.get('sigma_sb', 5.6704e-8)
        self.L_sun = CONSTANTS.get('L_sun', 3.826e26)
        self.b_wien = CONSTANTS.get('b_wien', 2.897e-3)
        self.R_sun = CONSTANTS.get('R_sun', 6.96e8)
        
        # Planetary temperatures
        self.T_s_Earth = CONSTANTS.get('T_s_Earth', 288)
        self.T_s_Earth_eff = CONSTANTS.get('T_s_Earth_eff', 255)
        self.T_s_Mars = CONSTANTS.get('T_s_Mars', 210)
        self.T_s_Venus = CONSTANTS.get('T_s_Venus', 737)
        self.T_s_Mercury = CONSTANTS.get('T_s_Mercury', 440)
        self.T_s_Jupiter = CONSTANTS.get('T_s_Jupiter', 165)
        self.T_s_Saturn = CONSTANTS.get('T_s_Saturn', 134)
        self.T_s_Uranus = CONSTANTS.get('T_s_Uranus', 76)
        self.T_s_Neptune = CONSTANTS.get('T_s_Neptune', 72)
        
        # Stellar spectral types
        self.T_s_O_star = CONSTANTS.get('T_s_O_star', 30000)
        self.T_s_B_star = CONSTANTS.get('T_s_B_star', 20000)
        self.T_s_A_star = CONSTANTS.get('T_s_A_star', 9000)
        self.T_s_F_star = CONSTANTS.get('T_s_F_star', 7000)
        self.T_s_G_star = CONSTANTS.get('T_s_G_star', 5778)
        self.T_s_K_star = CONSTANTS.get('T_s_K_star', 4500)
        self.T_s_M_star = CONSTANTS.get('T_s_M_star', 3000)
        
        # Set current body's T_s
        self.T_s = self._get_T_s_for_body(body)
    
    def _get_T_s_for_body(self, body: str) -> float:
        """
        Get surface temperature for the specified body.
        
        Args:
            body: Name of celestial body
            
        Returns:
            Surface temperature T_s in kelvin
        """
        body_map = {
            'Sun': self.T_s_Sun,
            'Earth': self.T_s_Earth,
            'Mars': self.T_s_Mars,
            'Venus': self.T_s_Venus,
            'Mercury': self.T_s_Mercury,
            'Jupiter': self.T_s_Jupiter,
            'Saturn': self.T_s_Saturn,
            'Uranus': self.T_s_Uranus,
            'Neptune': self.T_s_Neptune,
            'O_star': self.T_s_O_star,
            'B_star': self.T_s_B_star,
            'A_star': self.T_s_A_star,
            'F_star': self.T_s_F_star,
            'G_star': self.T_s_G_star,
            'K_star': self.T_s_K_star,
            'M_star': self.T_s_M_star,
        }
        return body_map.get(body, self.T_s_Sun)
    
    # ═══════════════════════════════════════════════════════════════════════════
    # UNIT CONVERSION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def kelvin_to_celsius(self, T_K: float) -> float:
        """
        Convert temperature from Kelvin to Celsius.
        
        Args:
            T_K: Temperature in kelvin (K)
            
        Returns:
            Temperature in Celsius (°C)
        """
        return T_K - 273.15
    
    def celsius_to_kelvin(self, T_C: float) -> float:
        """
        Convert temperature from Celsius to Kelvin.
        
        Args:
            T_C: Temperature in Celsius (°C)
            
        Returns:
            Temperature in kelvin (K)
        """
        return T_C + 273.15
    
    def kelvin_to_fahrenheit(self, T_K: float) -> float:
        """
        Convert temperature from Kelvin to Fahrenheit.
        
        Args:
            T_K: Temperature in kelvin (K)
            
        Returns:
            Temperature in Fahrenheit (°F)
        """
        return (T_K - 273.15) * 9/5 + 32
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEFAN-BOLTZMANN LAW METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def compute_luminosity(self, R: float, T: float = None) -> float:
        """
        Compute luminosity using Stefan-Boltzmann law.
        
        L = 4πR²σT⁴
        
        Args:
            R: Radius in meters
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Luminosity in watts (W)
        """
        if T is None:
            T = self.T_s
        return 4 * np.pi * R**2 * self.sigma_sb * T**4
    
    def compute_temperature_from_luminosity(self, L: float, R: float) -> float:
        """
        Compute effective temperature from luminosity and radius.
        
        T = (L / (4πR²σ))^(1/4)
        
        Args:
            L: Luminosity in watts (W)
            R: Radius in meters
            
        Returns:
            Effective temperature in kelvin (K)
        """
        return (L / (4 * np.pi * R**2 * self.sigma_sb))**(1/4)
    
    def compute_flux(self, T: float = None) -> float:
        """
        Compute surface flux (power per unit area).
        
        F = σT⁴
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Surface flux in W/m²
        """
        if T is None:
            T = self.T_s
        return self.sigma_sb * T**4
    
    # ═══════════════════════════════════════════════════════════════════════════
    # WIEN'S LAW METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def compute_peak_wavelength(self, T: float = None) -> float:
        """
        Compute peak emission wavelength using Wien's displacement law.
        
        λ_max = b/T where b = 2.897×10⁻³ m·K
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Peak wavelength in meters
        """
        if T is None:
            T = self.T_s
        return self.b_wien / T
    
    def compute_peak_wavelength_nm(self, T: float = None) -> float:
        """
        Compute peak emission wavelength in nanometers.
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Peak wavelength in nanometers (nm)
        """
        return self.compute_peak_wavelength(T) * 1e9
    
    def get_color_from_temperature(self, T: float = None) -> str:
        """
        Get approximate color of a blackbody at given temperature.
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Color name string
        """
        if T is None:
            T = self.T_s
        
        # Approximate color mapping based on temperature
        if T > 25000:
            return 'blue'
        elif T > 10000:
            return 'blue-white'
        elif T > 7500:
            return 'white'
        elif T > 6000:
            return 'yellow-white'
        elif T > 5000:
            return 'yellow'
        elif T > 4000:
            return 'orange'
        elif T > 3000:
            return 'orange-red'
        else:
            return 'red'
    
    # ═══════════════════════════════════════════════════════════════════════════
    # SPECTRAL CLASSIFICATION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def get_spectral_type(self, T: float = None) -> str:
        """
        Get stellar spectral type from temperature.
        
        Classification: O B A F G K M (hot to cool)
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Spectral type string (e.g., 'G2' for Sun)
        """
        if T is None:
            T = self.T_s
        
        if T >= 30000:
            return 'O'
        elif T >= 10000:
            return 'B'
        elif T >= 7500:
            return 'A'
        elif T >= 6000:
            return 'F'
        elif T >= 5200:
            return 'G'  # Sun is G2V
        elif T >= 3700:
            return 'K'
        else:
            return 'M'
    
    def get_spectral_type_detailed(self, T: float = None) -> str:
        """
        Get detailed spectral type with subclass.
        
        Args:
            T: Temperature in kelvin (defaults to current body's T_s)
            
        Returns:
            Detailed spectral type (e.g., 'G2' for Sun)
        """
        if T is None:
            T = self.T_s
        
        base_type = self.get_spectral_type(T)
        
        # Compute subclass (0-9 scale within each type)
        type_ranges = {
            'O': (30000, 50000),
            'B': (10000, 30000),
            'A': (7500, 10000),
            'F': (6000, 7500),
            'G': (5200, 6000),
            'K': (3700, 5200),
            'M': (2400, 3700)
        }
        
        if base_type in type_ranges:
            T_min, T_max = type_ranges[base_type]
            # Higher temp = lower subclass number
            fraction = (T_max - T) / (T_max - T_min)
            subclass = int(min(9, max(0, fraction * 10)))
            return f"{base_type}{subclass}"
        
        return base_type
    
    # ═══════════════════════════════════════════════════════════════════════════
    # VALIDATION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def validate_sun_temperature(self) -> dict:
        """
        Validate Sun's temperature using Stefan-Boltzmann law.
        
        Document specification:
            T_s = 5778 K (Sun)
            L_sun = 3.826×10²⁶ W
            R_sun = 6.96×10⁸ m
        
        Returns:
            Validation result dictionary
        """
        # Compute T from L and R
        T_computed = self.compute_temperature_from_luminosity(self.L_sun, self.R_sun)
        
        # Compute L from T and R
        L_computed = self.compute_luminosity(self.R_sun, self.T_s_Sun)
        
        return {
            'T_s_Sun': self.T_s_Sun,
            'T_computed_from_L_R': T_computed,
            'T_ratio': T_computed / self.T_s_Sun,
            'L_sun': self.L_sun,
            'L_computed_from_T_R': L_computed,
            'L_ratio': L_computed / self.L_sun,
            'valid': abs(T_computed - self.T_s_Sun) / self.T_s_Sun < 0.01  # Within 1%
        }
    
    def validate_wien_law(self) -> dict:
        """
        Validate Wien's displacement law for the Sun.
        
        Document specification:
            λ_max = b/T = 2.897×10⁻³/5778 ≈ 501 nm (green)
        
        Returns:
            Validation result dictionary
        """
        lambda_max = self.compute_peak_wavelength(self.T_s_Sun)
        lambda_max_nm = lambda_max * 1e9
        expected_nm = 501  # Approximately green
        
        return {
            'T_s_Sun': self.T_s_Sun,
            'lambda_max_m': lambda_max,
            'lambda_max_nm': lambda_max_nm,
            'expected_nm': expected_nm,
            'color': self.get_color_from_temperature(self.T_s_Sun),
            'spectral_type': self.get_spectral_type(self.T_s_Sun),
            'valid': abs(lambda_max_nm - expected_nm) < 10  # Within 10 nm
        }


