    def compute_E_react_contribution(self, 
                                      rho_SCm: float = None,
                                      v_SCm: float = None,
                                      t_days: float = 0.0,
                                      kappa: float = None) -> Tuple[float, str]:
        """
        Compute E_react using ρ_vac,A as normalization.
        
        E_react = (ρ_vac,[SCm] × v_SCm²) / ρ_vac,A × e^(-κt)
        
        Args:
            rho_SCm: [SCm] vacuum density (default from CONSTANTS)
            v_SCm: [SCm] velocity (default from CONSTANTS)
            t_days: Time in days
            kappa: Decay rate (default from CONSTANTS)
            
        Returns:
            Tuple of (E_react value, explanation string)
        """
        # Use defaults from CONSTANTS
        if rho_SCm is None:
            rho_SCm = CONSTANTS.get('rho_vac_SCm', 7.09e-37)
        if v_SCm is None:
            v_SCm = CONSTANTS.get('v_SCm', 1e8)
        if kappa is None:
            kappa = CONSTANTS.get('kappa', 0.0005)
        
        # Compute E_react
        numerator = rho_SCm * v_SCm**2
        denominator = self.rho_vac_A
        base_E_react = numerator / denominator
        decay_factor = np.exp(-kappa * t_days)
        E_react = base_E_react * decay_factor
        
        # Compare to simplified value (10^46)
        E_react_simplified = CONSTANTS.get('E_react_0', 1e46) * decay_factor
        
        explanation = f"""
    E_react CALCULATION WITH ρ_vac,A NORMALIZATION
    ═══════════════════════════════════════════════════════════════════════════════
    
    Formula:
        E_react = (ρ_vac,[SCm] × v_SCm²) / ρ_vac,A × e^(-κt)
    
    Parameters:
        ρ_vac,[SCm] = {rho_SCm:.4e} J/m³
        v_SCm       = {v_SCm:.4e} m/s
        ρ_vac,A     = {self.rho_vac_A:.4e} J/m³
        κ           = {kappa} day⁻¹
        t           = {t_days} days
    
    Step 1: Numerator
        ρ_vac,[SCm] × v_SCm² = {rho_SCm:.4e} × ({v_SCm:.4e})²
                              = {rho_SCm:.4e} × {v_SCm**2:.4e}
                              = {numerator:.4e} J·m²/s²
    
    Step 2: Normalization by ρ_vac,A
        Base E_react = {numerator:.4e} / {self.rho_vac_A:.4e}
                     = {base_E_react:.4e}
    
    Step 3: Time decay
        Decay factor = e^(-{kappa} × {t_days})
                     = e^(-{kappa * t_days:.6f})
                     = {decay_factor:.6f}
    
    Step 4: Final E_react
        E_react = {base_E_react:.4e} × {decay_factor:.6f}
        E_react = {E_react:.4e}
    
    Comparison to Simplified Value:
        Simplified: E_react = 10⁴⁶ × e^(-κt) = {E_react_simplified:.4e}
        Ratio: {E_react / E_react_simplified:.4e}
    
    Role of ρ_vac,A:
        • Provides universal normalization constant
        • Ensures E_react is scale-independent at cosmic level
        • Links [SCm] energy to Universal Aether background
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return E_react, explanation
    
    def compute_stress_energy_contribution(self, 
                                           t_n: float = 0.0) -> Tuple[float, str]:
        """
        Compute ρ_vac,A contribution to stress-energy tensor T_s^μν.
        
        Args:
            t_n: Negative time parameter
            
        Returns:
            Tuple of (contribution, explanation string)
        """
