# SCm PENETRATION MODEL (P_SCm)
# ═══════════════════════════════════════════════════════════════════════════════

class SCmPenetrationModel:
    """
    ╔═══════════════════════════════════════════════════════════════════════════════╗
    ║            SCm PENETRATION MODEL - P_SCm ANALYSIS                             ║
    ╠═══════════════════════════════════════════════════════════════════════════════╣
    ║                                                                               ║
    ║  P_SCm = [SCm] penetration factor (dimensionless)                            ║
    ║                                                                               ║
    ║  Definition:                                                                  ║
    ║    Quantifies how deeply [SCm] (Superconductive Material) penetrates         ║
    ║    or interacts with a celestial body's interior.                            ║
    ║                                                                               ║
    ║  VALUES BY BODY TYPE:                                                         ║
    ║  ─────────────────────────────────────────────────────────────────────────── ║
    ║  Stars (plasma):     P_SCm ≈ 1     (full penetration)                        ║
    ║  Planets (solid):    P_SCm ≈ 10⁻³  (reduced penetration)                     ║
    ║  Magnetars:          P_SCm ≈ 10    (enhanced interaction)                    ║
    ║  Neutron stars:      P_SCm ≈ 5     (high density enhancement)                ║
    ║                                                                               ║
    ║  PHYSICAL INTERPRETATION:                                                     ║
    ║  ─────────────────────────────────────────────────────────────────────────── ║
    ║  [SCm] is massless, extra-universal material that reacts with [UA] to       ║
    ║  drive universal dynamics. P_SCm reflects penetration effectiveness:         ║
    ║                                                                               ║
    ║  • Stars: High conductivity plasma allows fields to permeate fully          ║
    ║  • Planets: Solid/liquid barriers reduce penetration                         ║
    ║  • Magnetars: Extreme B-fields enhance [SCm] interaction                     ║
    ║                                                                               ║
    ║  ROLE IN Um:                                                                  ║
    ║  ─────────────────────────────────────────────────────────────────────────── ║
    ║  Um = Σ_j[μ_j/r_j·(1-e^(-γt·cos(πt_n)))·φ̂_j]·P_SCm·E_react×...            ║
    ║                                                                               ║
    ║  P_SCm directly scales magnetic energy density:                              ║
    ║    Sun (P_SCm=1):      Um ≈ 2.28×10⁶⁵ J/m³                                  ║
    ║    Planet (P_SCm=10⁻³): Um ≈ 2.28×10⁶² J/m³                                 ║
    ║                                                                               ║
    ╚═══════════════════════════════════════════════════════════════════════════════╝
    
    ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
    """
    
    # Body type classifications
    BODY_TYPES = {
        'star': 1.0,
        'sun': 1.0,
        'planet': 1e-3,
        'earth': 1e-3,
        'mars': 1e-3,
        'jupiter': 1e-3,
        'magnetar': 10.0,
        'neutron_star': 5.0,
        'pulsar': 5.0,
        'white_dwarf': 2.0,
        'brown_dwarf': 0.5,
        'moon': 1e-4,
        'asteroid': 1e-5,
    }
    
    def __init__(self):
        """Initialize SCm penetration model."""
        self.P_SCm_Sun = CONSTANTS.get('P_SCm_Sun', 1.0)
        self.P_SCm_planet = CONSTANTS.get('P_SCm_planet', 1e-3)
        self.P_SCm_magnetar = CONSTANTS.get('P_SCm_magnetar', 10.0)
        self.Um_Sun = CONSTANTS.get('Um_Sun', 2.28e65)  # Reference Um for Sun
    
    def get_P_SCm(self, body_type: str) -> float:
        """
        Get P_SCm value for a given body type.
        
        Args:
            body_type: Type of celestial body ('star', 'planet', 'magnetar', etc.)
            
        Returns:
            P_SCm penetration factor value
        """
        body_lower = body_type.lower().replace(' ', '_')
        
        # Check predefined types
        if body_lower in self.BODY_TYPES:
            return self.BODY_TYPES[body_lower]
        
        # Check CONSTANTS
        const_key = f'P_SCm_{body_lower}'
        if const_key in CONSTANTS:
            return CONSTANTS[const_key]
        
        # Default to star value
        return 1.0
    
    def compute_Um_scaling(self, body_type: str) -> dict:
        """
        Compute Um scaling based on P_SCm for body type.
        
        Args:
            body_type: Type of celestial body
            
        Returns:
            Dictionary with Um scaling information
        """
        P_SCm = self.get_P_SCm(body_type)
        Um_scaled = self.Um_Sun * P_SCm
        
        return {
            'body_type': body_type,
            'P_SCm': P_SCm,
            'Um_reference': self.Um_Sun,
            'Um_scaled': Um_scaled,
            'reduction_factor': 1.0 / P_SCm if P_SCm > 0 else float('inf'),
            'unit': 'J/m³'
        }
    
    def compare_stellar_planetary(self) -> dict:
        """
        Compare P_SCm and Um between stellar and planetary bodies.
        
        Returns:
            Comparison dictionary
        """
        stellar = self.compute_Um_scaling('star')
        planetary = self.compute_Um_scaling('planet')
        magnetar = self.compute_Um_scaling('magnetar')
        
        return {
            'stellar': stellar,
            'planetary': planetary,
            'magnetar': magnetar,
            'stellar_to_planetary_ratio': stellar['P_SCm'] / planetary['P_SCm'],
            'magnetar_to_stellar_ratio': magnetar['P_SCm'] / stellar['P_SCm'],
            'interpretation': (
                'P_SCm reflects [SCm] penetration into body interior. '
                'Stars (plasma) have full penetration (P_SCm=1), '
                'planets (solid/liquid) have reduced penetration (P_SCm=10⁻³), '
                'magnetars have enhanced interaction (P_SCm=10).'
            )
        }
    
    def get_penetration_physics(self, body_type: str) -> dict:
        """
        Get physical explanation for P_SCm value.
        
        Args:
            body_type: Type of celestial body
            
        Returns:
            Dictionary with physical interpretation
        """
        P_SCm = self.get_P_SCm(body_type)
        body_lower = body_type.lower()
        
        if 'star' in body_lower or 'sun' in body_lower:
            physics = {
                'interior_type': 'Plasma',
                'conductivity': 'High',
                'penetration': 'Full',
                'reason': 'Plasma allows magnetic fields and [SCm] to permeate throughout volume'
            }
        elif 'planet' in body_lower or 'earth' in body_lower:
            physics = {
                'interior_type': 'Solid/Liquid',
                'conductivity': 'Lower',
                'penetration': 'Reduced',
                'reason': 'Solid or liquid layers create barriers to [SCm] penetration'
            }
        elif 'magnetar' in body_lower:
            physics = {
                'interior_type': 'Neutron-degenerate',
                'conductivity': 'Extreme',
                'penetration': 'Enhanced',
                'reason': 'Extreme magnetic field (10¹⁴-10¹⁵ T) enhances [SCm] interaction'
            }
        elif 'neutron' in body_lower or 'pulsar' in body_lower:
            physics = {
                'interior_type': 'Neutron-degenerate',
                'conductivity': 'Very high',
                'penetration': 'Enhanced',
                'reason': 'Dense neutron matter allows strong [SCm] coupling'
            }
        else:
            physics = {
                'interior_type': 'Unknown',
                'conductivity': 'Variable',
                'penetration': 'Estimated',
                'reason': 'Body type not in standard classifications'
            }
        
        physics['P_SCm'] = P_SCm
        physics['body_type'] = body_type
        return physics
    
    def validate_document_example(self) -> dict:
        """
        Validate against document examples.
        
        Document specifies:
        - Sun: P_SCm ~ 1, Um ≈ 2.28×10⁶⁵ J/m³
        - Planet: P_SCm ~ 10⁻³, Um ≈ 2.28×10⁶² J/m³
        
        Returns:
            Validation results
        """
        # Sun validation
        sun_result = self.compute_Um_scaling('sun')
        sun_P_expected = 1.0
        sun_Um_expected = 2.28e65
        sun_P_match = abs(sun_result['P_SCm'] - sun_P_expected) < 0.01
        sun_Um_match = abs(sun_result['Um_scaled'] - sun_Um_expected) / sun_Um_expected < 0.01
        
        # Planet validation
        planet_result = self.compute_Um_scaling('planet')
        planet_P_expected = 1e-3
        planet_Um_expected = 2.28e62
        planet_P_match = abs(planet_result['P_SCm'] - planet_P_expected) < 1e-4
        planet_Um_match = abs(planet_result['Um_scaled'] - planet_Um_expected) / planet_Um_expected < 0.01
        
        all_pass = sun_P_match and sun_Um_match and planet_P_match and planet_Um_match
        
        return {
            'sun': {
                'P_SCm_expected': sun_P_expected,
                'P_SCm_computed': sun_result['P_SCm'],
                'P_SCm_match': sun_P_match,
                'Um_expected': sun_Um_expected,
                'Um_computed': sun_result['Um_scaled'],
                'Um_match': sun_Um_match
            },
            'planet': {
                'P_SCm_expected': planet_P_expected,
                'P_SCm_computed': planet_result['P_SCm'],
                'P_SCm_match': planet_P_match,
                'Um_expected': planet_Um_expected,
                'Um_computed': planet_result['Um_scaled'],
                'Um_match': planet_Um_match
            },
            'all_validations_pass': all_pass
        }
    
