        self.Ug2_Sun = 1.18e53  # J/m³
        self.Ug3_Sun = 1.8e49   # J/m³
        self.Ug4_Sun = 2.5e-20  # J/m³
        self.Ubi_Sun = -1.94e27  # J/m³
